    ["Extra settings added to every reply, written as a JSON object, for example {example}. Use it for samplers that have no box above. A setting that has its own box above is refused. If a server refuses a setting, it is left out and the reply still comes."] = "모든 응답에 추가되는 추가 설정으로, JSON 객체로 씁니다(예: {example}). 위에 칸이 없는 샘플러용입니다. 위에 자체 칸이 있는 설정은 거부됩니다. 서버가 설정을 거부하면 그 설정은 빠지고 응답은 그대로 옵니다.",
    ["Mistral takes only the settings shown here. Top K, Min P and the advanced JSON are for Local AI and Custom models."] = "Mistral은 여기 표시된 설정만 받습니다. Top K, Min P, 고급 JSON은 Local AI 및 사용자 지정 모델용입니다.",
    ["Mistral does not take this setting."] = "Mistral은 이 설정을 받지 않습니다.",
    ["That is not valid JSON."] = "올바른 JSON이 아닙니다.",
    ["This must be a JSON object, for example {example}."] = "JSON 객체여야 합니다(예: {example}).",
    ["Too many keys. Keep {max} or fewer."] = "키가 너무 많습니다. {max}개 이하로 유지하세요.",
    ["“{name}” is not a usable key name. Use letters, digits and underscores."] = "“{name}”은(는) 사용할 수 없는 키 이름입니다. 문자, 숫자, 밑줄만 사용하세요.",
    ["“{name}” has its own setting in this form. Use that instead."] = "“{name}”은(는) 이 양식에 자체 설정이 있습니다. 그것을 대신 사용하세요.",
    ["Use the Longest reply box for the length of a reply, not “{name}”."] = "응답 길이는 “최대 응답 길이” 칸을 사용하세요. “{name}”이(가) 아닙니다.",
    ["“{name}” is set by the mod and cannot be changed here."] = "“{name}”은(는) 모드가 설정하며 여기서 바꿀 수 없습니다.",
    ["“{name}” needs a number, a text, true or false, or a list of those."] = "“{name}”에는 숫자, 텍스트, true 또는 false, 또는 이들의 목록이 필요합니다.",
    ["Longest character description, in characters"] = "캐릭터 설명 최대 길이(글자 수)",
    ["Earlier turns kept"] = "유지할 이전 대화 수",
    ["Right-now sentence"] = "“지금 있는 곳” 문장",
    ["Notes for this turn"] = "이번 응답 메모",
    ["That prompting option was not found."] = "해당 프롬프트 옵션을 찾을 수 없습니다.",
    ["Keep at least one rule."] = "규칙을 하나 이상 남겨 두세요.",
    ["Rule {n} is empty. Write the rule or delete it."] = "규칙 {n}이(가) 비어 있습니다. 규칙을 작성하거나 삭제하세요.",
    ["Rule {n} is too long. Keep each one under {max} characters."] = "규칙 {n}이(가) 너무 깁니다. 각 규칙은 {max}자 미만으로 하세요.",
    ["The rules are too long together. Keep them under {max} characters in all."] = "규칙들을 합치면 너무 깁니다. 전부 합쳐 {max}자 미만으로 하세요.",
    ["This text is too long. Keep it under {max} characters."] = "이 텍스트는 너무 깁니다. {max}자 미만으로 하세요.",
    ["This text cannot be empty."] = "이 텍스트는 비워 둘 수 없습니다.",
    ["Use a number from {min} to {max}."] = "{min}에서 {max} 사이의 숫자를 입력하세요.",
    ["Too many stop texts. Keep {max} or fewer."] = "중단 문구가 너무 많습니다. {max}개 이하로 하세요.",
    ["A stop text is too long. Keep each one under {max} characters."] = "중단 문구가 너무 깁니다. 각 문구는 {max}자 미만으로 하세요.",
    ["{field}: {message}"] = "{field}: {message}",
    ["In use now"] = "현재 사용 중",
    ["How each conversation option is told to answer. Every option has its own prompting. A change counts from the next reply, and nothing needs restarting."] = "각 대화 옵션이 어떻게 답해야 하는지 지정합니다. 옵션마다 고유한 프롬프트가 있습니다. 변경 사항은 다음 응답부터 적용되며, 재시작할 필요가 없습니다.",
    ["The facts the characters get from the game and a short list of safety filters cannot be edited here. Convai’s prompting lives on Convai’s side."] = "게임에서 캐릭터가 얻는 사실과 짧은 안전 필터 목록은 여기서 편집할 수 없습니다. Convai의 프롬프트는 Convai 쪽에 있습니다.",
    ["Mistral and Local AI"] = "Mistral 및 Local AI",
    ["Lite and Standard are the two Local AI model sizes. “Mature on” is used while Mature content is on."] = "Lite와 Standard는 Local AI의 두 가지 모델 크기입니다. “성인 콘텐츠 켜짐”은 성인 콘텐츠가 켜져 있을 때 사용됩니다.",
    ["Your Custom models and APIs"] = "사용자 지정 모델 및 API",
    ["A Custom model appears here once you choose Custom as the conversation provider and set a model."] = "대화 제공자로 사용자 지정을 선택하고 모델을 설정하면 여기에 사용자 지정 모델이 표시됩니다.",
    ["From {min} to {max}."] = "{min}부터 {max}까지.",
    ["Shipped: {value}"] = "기본값: {value}",
    ["Rule {n}"] = "규칙 {n}",
    ["Rule {n}, for a speaker with a reply length of its own"] = "규칙 {n}, 고유한 응답 길이를 가진 화자용",
    ["Rule {n}, for Mature content"] = "규칙 {n}, 성인 콘텐츠용",
    ["Move rule {n} up"] = "규칙 {n}을(를) 위로 이동",
    ["Move up"] = "위로 이동",
    ["Move rule {n} down"] = "규칙 {n}을(를) 아래로 이동",
    ["Move down"] = "아래로 이동",
    ["Delete rule {n}"] = "규칙 {n} 삭제",
    ["Other versions of this rule"] = "이 규칙의 다른 버전",
    ["Leave a version empty to use the rule text."] = "버전을 비워 두면 규칙 텍스트를 사용합니다.",
    ["For a speaker with a reply length of its own"] = "고유한 응답 길이를 가진 화자용",
    ["For Mature content"] = "성인 콘텐츠용",
    ["Shipped: off"] = "기본값: 꺼짐",
    ["Shipped: the mod’s own limit"] = "기본값: 모드 자체 제한",
    ["before V’s words"] = "V의 대사 앞",
    ["after V’s words"] = "V의 대사 뒤",
    ["Repeat the “where you are” sentence right before V’s words"] = "“지금 있는 곳” 문장을 V의 대사 바로 앞에 반복",
    ["The notes for this turn go"] = "이번 응답 메모 위치",
    ["Output rules"] = "출력 규칙",
    ["The numbered rules the model reads before every reply. Use {name} for the character’s name and {words} for the reply length of a speaker that has one."] = "모델이 매번 응답하기 전에 읽는 번호 매긴 규칙입니다. 캐릭터 이름에는 {name}을, 고유한 응답 길이가 있는 화자의 응답 길이에는 {words}를 사용하세요.",
    ["Example replies"] = "예시 응답",
    ["Replies shown to the model after the rules. A small model may copy them word for word, so add none, or keep them short and plain."] = "규칙 다음에 모델에 보여 주는 응답입니다. 작은 모델은 그대로 따라 쓸 수 있으므로 추가하지 않거나, 짧고 평이하게 작성하세요.",
    ["Add an example reply"] = "예시 응답 추가",
    ["An example reply"] = "예시 응답",
    ["Example reply {n}"] = "예시 응답 {n}",
    ["Opening line"] = "여는 문장",
    ["The first line of the character text. Use {name} for the character’s name."] = "캐릭터 텍스트의 첫 줄입니다. 캐릭터 이름에는 {name}을 사용하세요.",
    ["The last thing the model reads before it answers. Use {name} for the character’s name and {words} for the reply length. The Mature setting adds its own clause after it."] = "모델이 답하기 전에 마지막으로 읽는 내용입니다. 캐릭터 이름에는 {name}을, 응답 길이에는 {words}를 사용하세요. 성인 콘텐츠 설정은 그 뒤에 자체 문장을 덧붙입니다.",
    ["Section headings"] = "섹션 제목",
    ["The headings that mark each part of the prompt. Change the wording, not the order."] = "프롬프트의 각 부분을 나타내는 제목입니다. 문구는 바꿀 수 있지만 순서는 바꿀 수 없습니다.",
    ["Layout"] = "배치",
    ["Where some notes go in the prompt."] = "프롬프트에서 일부 메모를 넣을 위치입니다.",
    ["Sampling"] = "샘플링",
    ["How freely the model words its reply. Leave a box empty to use the shipped value."] = "모델이 응답의 단어를 얼마나 자유롭게 고르는지 정합니다. 칸을 비워 두면 기본값을 사용합니다.",
    ["Length limits"] = "길이 제한",
    ["Shorten what the model reads, which makes replies faster. The mod’s own limits still apply, so these can only make things shorter."] = "모델이 읽는 분량을 줄이면 응답이 빨라집니다. 모드 자체의 제한은 그대로 적용되므로, 여기서는 더 짧게만 할 수 있습니다.",
    ["Stop texts"] = "중단 문구",
    ["Mature layer"] = "성인 레이어",
    ["The wording added while Mature content is on. The mod picks the explicit or the suggestive version of a line from what the loaded model allows, so edit the version your model uses. An emptied box leaves that line out. The adults-only line and the hard limits are always added last and cannot be edited."] = "성인 콘텐츠가 켜져 있을 때 추가되는 표현입니다. 모드는 불러온 모델이 허용하는 범위에서 각 대사의 명시적 버전이나 암시적 버전을 고르므로, 사용하는 모델이 쓰는 버전을 편집하세요. 칸을 비우면 그 대사는 빠집니다. 성인 전용 문장과 기본 제한은 항상 마지막에 추가되며 편집할 수 없습니다.",
    ["Speech line"] = "말투 문장",
    ["Word bank"] = "단어 목록",
    ["Romance line"] = "로맨스 문장",
    ["Closing clause"] = "마무리 구절",
    ["Tone line"] = "어조 문장",
    ["Partner paragraph: affection and desire"] = "파트너 단락: 애정과 욕망",
    ["Partner paragraph: nothing invented"] = "파트너 단락: 지어내지 않기",
    ["{part}, for models that allow explicit sex"] = "{part}, 노골적인 성적 묘사를 허용하는 모델용",
    ["{part}, for models that keep sex suggestive"] = "{part}, 성적 묘사를 암시에 그치는 모델용",
    ["This option does not get the Mature layer."] = "이 옵션에는 성인 레이어가 적용되지 않습니다.",
    ["Mature layer and closing line, for models that allow explicit sex"] = "성인 레이어와 마무리 문장, 노골적인 성적 묘사를 허용하는 모델용",
    ["Mature layer and closing line, for models that keep sex suggestive"] = "성인 레이어와 마무리 문장, 성적 묘사를 암시에 그치는 모델용",
    ["A reply ends when the model writes one of these. Line breaks count. Up to {max}."] = "모델이 이 중 하나를 쓰면 응답이 끝납니다. 줄바꿈도 포함됩니다. 최대 {max}개.",
    ["Add a stop text"] = "중단 문구 추가",
    ["A text that ends the reply"] = "응답을 끝내는 문구",
    ["Stop text {n}"] = "중단 문구 {n}",
    ["Preview"] = "미리보기",
    ["The prompt text as the model would read it for a sample character. It follows your edits as you type, before you save."] = "샘플 캐릭터에 대해 모델이 읽을 프롬프트 텍스트입니다. 저장하기 전에도 입력하는 대로 편집 내용이 반영됩니다.",
    ["Sample character name"] = "샘플 캐릭터 이름",
    ["A speaker with a reply length of its own"] = "고유한 응답 길이를 가진 화자",
    ["Reply length in words"] = "응답 길이(단어 수)",
    ["Mature content is on"] = "성인 콘텐츠가 켜져 있음",
    ["The preview waits until the problems in the form are fixed."] = "양식의 문제를 고칠 때까지 미리보기는 대기합니다.",
    ["No example replies."] = "예시 응답이 없습니다.",
    ["No closing line."] = "마무리 문장이 없습니다.",
    ["Go back to the shipped prompting for {name}? Your changes to this part are removed."] = "{name}의 기본 프롬프트로 되돌릴까요? 이 항목에 대한 변경 사항은 삭제됩니다.",
    ["Go back to the shipped prompting for {name}? All your changes to it are removed."] = "{name}의 기본 프롬프트로 되돌릴까요? 이에 대한 변경 사항은 모두 삭제됩니다.",
    ["Back to the shipped prompting."] = "기본 프롬프트로 되돌립니다.",
    ["Prompting"] = "프롬프트",
    ["Street reputation"] = "거리 평판",
    ["Gangs, the NCPD, corporations and the locals of each district remember what V did: Street Cred, choices in jobs, fights, crimes the police saw and how you treat people. It shapes their greeting, trust and help.\n\nOnly ordinary people, never named or story characters. It changes their words, nothing in the game."] = "갱단, NCPD, 기업, 각 지구 주민들은 V가 한 일을 기억합니다: 스트리트 크레드, 일에서의 선택, 싸움, 경찰이 본 범죄, 사람을 대하는 방식. 인사, 신뢰, 도움이 그에 따라 달라집니다.\n\n평범한 사람들만 해당되며, 이름 있는 캐릭터나 스토리 캐릭터는 제외됩니다. 말만 바뀌고 게임에는 영향이 없습니다.",
    ["NPCs react to threats and commands"] = "NPC가 위협과 명령에 반응",
    ["Ordinary people you threaten run, cower or fight back, as their kind would: gang members and guards use their fists for an insult and their weapons for a death threat.\n\nThey may also do what you tell them, if they would: get down, stop, or get out of the vehicle.\n\nOnly ordinary people, never named or story characters, and never during scenes, quests or fights."] = "위협받은 일반인은 성향에 따라 도망치거나, 겁에 질려 웅크리거나, 맞섭니다. 갱단원과 경비원은 모욕에는 주먹으로, 죽이겠다는 위협에는 무기로 대응합니다.\n\n그럴 만한 사람이라면 시키는 대로도 합니다: 엎드리기, 멈추기, 차에서 내리기.\n\n일반인에게만 적용되며, 이름 있는 캐릭터나 스토리 캐릭터에게는 절대 적용되지 않고, 장면, 퀘스트, 전투 중에는 일어나지 않습니다.",
    ["Voice language"] = "음성 언어",
    ["English"] = "영어",
    ["Automatic"] = "자동",
    ["Polish"] = "폴란드어",
    ["Russian"] = "러시아어",
    ["Ukrainian"] = "우크라이나어",
    ["Turkish"] = "터키어",
    ["Czech"] = "체코어",
    ["Hungarian"] = "헝가리어",
    ["Japanese"] = "일본어",
    ["Korean"] = "한국어",
    ["Chinese"] = "중국어",
    ["Choose one of the listed reply languages."] = "응답 언어 중 하나를 선택하세요.",
    ["No speech was heard. Hold the talk key while you speak."] = "음성이 들리지 않았습니다. 말하는 동안 음성 키를 누르고 계세요.",
    ["Voice activation"] = "음성 활성화",
    ["Voice activation could not open the microphone. Check your Windows input device."] = "음성 활성화에서 마이크를 열 수 없습니다. Windows 입력 장치를 확인하세요.",
    ["Voice input could not reach Convai. Hold the voice key again, or type."] = "음성 입력이 Convai에 연결하지 못했습니다. 음성 키를 다시 누르고 계시거나 직접 입력하세요.",
    ["Talk without a key. While you face a character or a companion is near, the mod listens and answers when you pause for about a second.\n\nNever during the game’s own scenes or choices, or while a character speaks. Nothing leaves your PC unless speech is heard. Headphones work best, but a Bluetooth headset’s microphone drops it to call quality while this listens."] = "키를 누르고 있지 않아도 말할 수 있습니다. 캐릭터를 마주 보고 있거나 동료가 가까이 있으면, 모드가 목소리를 듣고 약 1초 동안 말을 멈추면 대답합니다.\n\n게임 자체의 장면이나 대화 선택지 중, 캐릭터가 말하는 동안에는 절대 듣지 않습니다. 음성이 감지되지 않으면 PC에서 아무것도 나가지 않습니다. 헤드폰이 가장 좋고, 블루투스 헤드셋 마이크는 듣는 동안 통화 음질로 바뀝니다.",
    ["Opening microphone…"] = "마이크 여는 중…",
    ["Speak now"] = "지금 말하세요",
    ["Type in the search box to find a model by name or record, for example “rita wheeler”. A part of a word is enough."] = "검색창에 입력하면 이름이나 레코드로 모델을 찾을 수 있습니다. 예: “rita wheeler”. 단어의 일부만 입력해도 됩니다.",
    ["Content packs"] = "콘텐츠 팩",
    ["Add-ons that change how the characters talk."] = "캐릭터가 말하는 방식을 바꾸는 추가 기능.",
    ["Content packs add rules after yours. You cannot edit them here: turn a pack off under Settings > Content packs in the game."] = "콘텐츠 팩은 사용자의 규칙 뒤에 규칙을 추가합니다. 여기서는 편집할 수 없습니다. 게임에서 설정 > 콘텐츠 팩에서 팩을 끄세요.",
    ["From the content pack {name}"] = "콘텐츠 팩 {name}에서",
    ["Content packs that change this prompt: {names}. Your own changes stay on top of theirs, and Reset to default goes back to the pack’s wording."] = "이 프롬프트를 바꾸는 콘텐츠 팩: {names}. 사용자의 변경 사항은 팩의 변경 사항 위에 남고, 기본값으로 재설정하면 팩의 문구로 돌아갑니다.",
    ["Memory in use"] = "사용 중인 기억",
    ["Normal memory"] = "일반 기억",
    ["Forget memories clears only the memory shown here. The other memory stays as it is."] = "기억 삭제는 여기에 표시된 기억만 지웁니다. 다른 기억은 그대로 남습니다.",
    ["This clears the memory in use: {memory}."] = "사용 중인 기억을 지웁니다: {memory}.",
    ["Backspace"] = "백스페이스",
    ["Cancelled."] = "취소했습니다.",
    ["Caps lock"] = "CapsLock",
    ["Choose a key or a controller button."] = "키 또는 컨트롤러 버튼을 선택하세요.",
    ["Choose the keys and controller buttons for talking by voice or text, the group chats and the Companion Manager. They work at once."] = "음성이나 텍스트로 대화하기, 그룹 채팅, 동료 관리에 쓸 키와 컨트롤러 버튼을 선택하세요. 바로 적용됩니다.",
    ["Choose the keys and controller buttons for the mod’s actions. Press Set, then the key or button you want. Esc or B cancels. A change works at once, and the keys you set in Cyber Engine Tweaks keep working. Pick keys the game does not already use."] = "모드 동작에 쓸 키와 컨트롤러 버튼을 선택하세요. ‘지정’을 누른 다음 원하는 키 또는 버튼을 누르세요. Esc 또는 B를 누르면 취소됩니다. 변경 사항은 바로 적용되며, Cyber Engine Tweaks에서 설정한 키도 계속 작동합니다. 게임에서 이미 쓰지 않는 키를 고르세요.",
    ["Controller {button}"] = "컨트롤러 {button}",
    ["D-pad down"] = "방향패드 아래",
    ["D-pad left"] = "방향패드 왼쪽",
    ["D-pad right"] = "방향패드 오른쪽",
    ["D-pad up"] = "방향패드 위",
    ["Down arrow"] = "아래 화살표",
    ["End"] = "End",
    ["Enter"] = "Enter",
    ["Group text chat"] = "그룹 텍스트 채팅",
    ["Group voice chat"] = "그룹 음성 채팅",
    ["Hold it to talk to the characters around you at once, and let go to send. Facing nobody, you talk to the first member of your party and two others from it."] = "누르고 있으면 주변의 캐릭터 모두에게 한꺼번에 말하고, 떼면 전송됩니다. 아무도 바라보지 않으면 파티의 첫 번째 멤버와 그 밖의 두 명에게 말합니다.",
    ["Hold it to talk to Johnny, the voice in your head, wherever you face, and let go to send. It needs Johnny in your head turned on in Settings."] = "누르고 있으면 어디를 보고 있든 머릿속의 목소리인 조니에게 말할 수 있고, 떼면 전송됩니다. 설정에서 머릿속의 조니를 켜야 합니다.",
    ["Hold the key or button while you speak and let go to send, like the Cyber Engine Tweaks talk key. Facing nobody, you talk to the first member of your party."] = "말하는 동안 키나 버튼을 누르고 있다가 떼면 전송됩니다. Cyber Engine Tweaks의 대화 키와 같은 방식입니다. 아무도 바라보지 않으면 파티의 첫 번째 멤버에게 말합니다.",
    ["Home"] = "Home",
    ["Insert"] = "Insert",
    ["Key bindings"] = "키 바인딩",
    ["Key bindings need Codeware, and this game does not have it. Open Help for what is missing."] = "키 바인딩에는 Codeware가 필요한데 이 게임에는 없습니다. 무엇이 부족한지 보려면 도움말을 여세요.",
    ["Key or button"] = "키 또는 버튼",
    ["Left arrow"] = "왼쪽 화살표",
    ["Menu"] = "메뉴",
    ["No key was pressed, so nothing changed."] = "키를 누르지 않아서 아무것도 바뀌지 않았습니다.",
    ["Not available"] = "사용 불가",
    ["Not set"] = "지정 안 됨",
    ["Num lock"] = "NumLock",
    ["Page down"] = "PgDn",
    ["Page up"] = "PgUp",
    ["Pause"] = "Pause",
    ["Press it, then the key or controller button you want. Esc or B cancels. It works at once."] = "이것을 누른 다음 원하는 키 또는 컨트롤러 버튼을 누르세요. Esc 또는 B로 취소합니다. 바로 적용됩니다.",
    ["Press it to open the Companion Manager while you play."] = "게임하는 동안 이 키를 누르면 동료 관리가 열립니다.",
    ["Press it to type to the character you face. Facing nobody, you type to the first member of your party."] = "눈앞의 캐릭터에게 글로 말하려면 이 키를 누르세요. 아무도 바라보지 않으면 파티의 첫 번째 멤버에게 글로 말합니다.",
    ["Press it to type to Johnny, the voice in your head, wherever you face. It needs Johnny in your head turned on in Settings."] = "어디를 보고 있든 머릿속의 목소리인 조니에게 글로 말하려면 이 키를 누르세요. 설정에서 머릿속의 조니를 켜야 합니다.",
    ["Press it to type to the characters around you at once. Facing nobody, you type to the first member of your party and two others from it."] = "주변의 캐릭터 모두에게 한꺼번에 글로 말하려면 이 키를 누르세요. 아무도 바라보지 않으면 파티의 첫 번째 멤버와 그 밖의 두 명에게 글로 말합니다.",
    ["Press the key or controller button for {action}. Esc or B cancels."] = "{action}에 사용할 키 또는 컨트롤러 버튼을 누르세요. Esc 또는 B로 취소합니다.",
    ["Print screen"] = "PrtSc",
    ["Remove the key or button you set here."] = "여기서 지정한 키 또는 버튼을 제거합니다.",
    ["Right arrow"] = "오른쪽 화살표",
    ["Scroll lock"] = "ScrLk",
    ["Space"] = "스페이스",
    ["Tab"] = "Tab",
    ["Talk by text"] = "텍스트로 대화",
    ["Talk by voice"] = "음성으로 대화",
    ["Talk to Johnny by text"] = "조니와 텍스트로 대화",
    ["Talk to Johnny by voice"] = "조니와 음성으로 대화",
    ["That key is already used for another action."] = "그 키는 이미 다른 동작에 사용되고 있습니다.",
    ["The mod’s key bindings could not be loaded. Open Help for what is wrong."] = "모드의 키 바인딩을 불러오지 못했습니다. 도움말을 열어 무엇이 잘못됐는지 확인하세요.",
    ["The mod’s scripts did not load, so no key can be set. Open Help for what is wrong."] = "모드의 스크립트가 로드되지 않아 키를 지정할 수 없습니다. 도움말을 열어 무엇이 잘못됐는지 확인하세요.",
    ["Up arrow"] = "위 화살표",
    ["View"] = "보기",
    ["{action} cleared."] = "{action} 지정을 해제했습니다.",
    ["{action} is set to {key}."] = "{action}: {key}(으)로 지정했습니다.",
    ["{key} is already used for {other}. Choose another."] = "{key}은(는) 이미 {other}에 사용되고 있습니다. 다른 키를 고르세요.",
    ["10 minutes"] = "10분",
    ["2 minutes"] = "2분",
    ["5 minutes"] = "5분",
    ["Cancel this meeting. She is not told."] = "약속 취소. 그녀에게 알리지 않음.",
    ["Car"] = "차로",
    ["Choose how long she waits."] = "얼마나 기다릴지 고르세요.",
    ["Choose how she arrives."] = "어떻게 도착할지 고르세요.",
    ["Choose one of the listed options."] = "목록에서 하나를 고르세요.",
    ["Choose when she arrives."] = "언제 도착할지 고르세요.",
    ["Companions travel to you when you invite them: they walk or drive in, text you, wait, and remember if you never come.\n\nOff by default."] = "초대하면 동료가 당신에게 찾아옵니다. 걸어서 또는 차로 오고, 메시지를 보내고, 기다리며, 당신이 오지 않으면 그것을 기억합니다.\n\n기본값은 꺼짐입니다.",
    ["Fine. Call me when you know what you want."] = "알겠어요. 하고 싶은 게 정해지면 연락해요.",
    ["How long she waits"] = "기다리는 시간",
    ["How long she waits for you after arriving right now. After a timed arrival she waits as long as the delay you chose. The wait stops while you are in a fight, a scene or a menu."] = "지금 도착한 뒤 그녀가 당신을 기다리는 시간입니다. 정해진 시간에 도착하면 선택한 지연 시간만큼 기다립니다. 전투, 장면, 메뉴 중에는 대기가 멈춥니다.",
    ["How she arrives"] = "도착 방식",
    ["I waited {minutes} minutes at {place} and you never showed. Forget it."] = "{place}에서 {minutes}분 기다렸는데 당신은 오지 않았어요. 됐어요.",
    ["I'm here at {place}. Where are you?"] = "{place}에 있어요. 어디예요?",
    ["Immersive invitations"] = "몰입형 초대",
    ["In 10 minutes"] = "10분 뒤",
    ["In 2 minutes"] = "2분 뒤",
    ["In 5 minutes"] = "5분 뒤",
    ["Invite a companion and she really travels to you: she appears out of sight, walks or drives in, texts you when she is there and waits for you."] = "동료를 초대하면 정말로 당신에게 옵니다. 시야 밖에 나타나 걸어서 또는 차로 다가오고, 도착하면 메시지를 보내고 당신을 기다립니다.",
    ["Meet at my waypoint when I ask"] = "요청하면 내 목표 지점으로 오기",
    ["Off: Invite brings a companion to your side at once.\n\nOn: a companion you invite, by the Invite button, the Contacts tab or a text, travels to you and arrives after the time you choose here. She texts you when she is there, waits, and leaves angry (and remembers it) if you never come."] = "꺼짐: 초대하면 동료가 바로 곁으로 옵니다.\n\n켜짐: 초대 버튼, 연락처 탭 또는 메시지로 초대한 동료는 여기서 고른 시간 뒤에 당신에게 도착합니다. 도착하면 메시지를 보내고 기다리며, 당신이 오지 않으면 화가 나서 떠나고 그것을 기억합니다.",
    ["Right now"] = "지금",
    ["Right now: she is on her way as soon as she is ready.\n\nIn 2, 5 or 10 minutes: real minutes of play, so she arrives at that time. She then waits as long as that delay."] = "지금: 준비되는 즉시 가는 중입니다.\n\n2분, 5분, 10분 뒤: 실제 플레이 시간이므로 그 시간에 도착합니다. 그 뒤에는 그 지연 시간만큼 기다립니다.",
    ["She texts you"] = "메시지 보내기",
    ["She texts you when she arrives, when you cancel and when she gives up. Off: no texts (she still remembers being stood up)."] = "도착했을 때, 취소했을 때, 포기했을 때 메시지를 보냅니다. 꺼짐: 메시지 없음 (바람맞힌 일은 여전히 기억합니다).",
    ["Something came up and I can't make it. Sorry."] = "일이 생겨서 못 갈 것 같아요. 미안해요.",
    ["Walk"] = "걸어서",
    ["Walk: she appears out of your sight and walks to you.\n\nCar: when a road is near she drives in, stops on the road, gets out and walks the rest. Without a road she walks. The car stays near for a ride, and is removed when she leaves your group or you both go far from it."] = "걸어서: 시야 밖에 나타나 당신에게 걸어옵니다.\n\n차로: 근처에 길이 있으면 차로 다가와 길가에 멈추고 내린 뒤 나머지는 걸어옵니다. 길이 없으면 걸어옵니다. 차는 함께 타기 위해 근처에 머물고, 그녀가 그룹을 떠나거나 둘 다 차에서 멀어지면 사라집니다.",
    ["When she arrives"] = "도착할 때",
    ["When you ask her to come to your waypoint and a map pin is set, she goes there and says so. Off: she always comes to where you are."] = "목표 지점으로 와 달라고 부탁했을 때 지도 핀이 찍혀 있으면 그곳으로 가서 알려 줍니다. 꺼짐: 항상 당신이 있는 곳으로 옵니다.",
    ["Your position cannot be read yet."] = "아직 당신의 위치를 읽을 수 없어요.",
    ["on her way"] = "가는 중",
    ["the meeting spot"] = "만날 장소",
    ["waiting at {place}"] = "{place}에서 기다리는 중",
    ["{name} is already on the way."] = "{name} 이미 가는 중이에요.",
    ["{name} is on her way."] = "{name} 가는 중이에요.",
    ["{name} is on her way. About {minutes} minutes."] = "{name} 가는 중이에요. 약 {minutes}분 남았어요.",
    ["{name} · {state}"] = "{name} · {state}",
    ["{name}: Good to see you. Let us go."] = "{name}: 반가워요. 가요.",
    ["Corpo Plaza"] = "Corpo Plaza",
    ["Heywood Glen"] = "Heywood Glen",
    ["Megabuilding H10"] = "Megabuilding H10",
    ["Move out"] = "나가게 하기",
    ["That companion is not available."] = "그 동료는 지금 이용할 수 없어요.",
    ["Watson Northside"] = "Watson Northside",
    ["Westbrook Japantown"] = "Westbrook Japantown",
    ["You do not have that apartment."] = "그 아파트는 없어요.",
    ["at home"] = "집에 있음",
    ["out"] = "외출 중",
    ["with you"] = "함께",
    ["{count} more housemates"] = "동거인 {count}명 더",
    ["{name} has moved out."] = "{name}이(가) 집을 나갔어요.",
    ["{name} is back at home."] = "{name}이(가) 다시 집에 돌아왔어요.",
    ["{name} joins you."] = "{name}이(가) 합류해요.",
    ["{name} moves into {apartment}."] = "{name}이(가) {apartment}(으)로 이사해요.",
    ["{name} now lives in {apartment} and stays in your party until sent home."] = "{name}이(가) 이제 {apartment}에서 살아요. 집으로 보내기 전까지는 파티에 남아 있어요.",
    ["{name} stops living at your place. She stays as she is otherwise."] = "{name}은(는) 더 이상 당신의 집에 살지 않아요. 그 밖에는 그대로예요.",
    ["{name} · lives in {apartment} · {state}"] = "{name} · {apartment}에 살아요 · {state}",
    ["Companions change outfits"] = "동료 의상 변경",
    ["Your party’s companions change outfits now and then: another look by day and by night, and casual clothes at home, where the character has them.\n\nOnly out of your sight, never in front of you, and only for your party’s own copies, never the game’s own characters. Turning this off keeps what they wear now."] = "파티의 동료들은 이따금 의상을 바꿉니다. 낮과 밤에 각각 다른 모습을 하고, 캐릭터가 가진 경우 집에서는 편한 옷을 입습니다.\n\n오직 시야 밖에서만 바뀌며, 눈앞에서는 절대 바뀌지 않습니다. 파티 소속 복제 동료에게만 적용되고, 게임 고유 캐릭터에게는 적용되지 않습니다. 이 옵션을 끄면 지금 입고 있는 옷을 그대로 유지합니다.",
    ["Choose how often companions speak up."] = "동료가 먼저 말하는 빈도를 고르세요.",
    ["Companions speak up"] = "동료가 먼저 말함",
    ["How V is doing according to other mods, when they are installed: Dark Future’s tiredness, hunger, thirst, nerve and addictions, for example. Also what V visibly wears while an Equipment-EX outfit is on, so characters describe the outfit and not the clothes it hides.\n\nOff by default. Off: it is not sent, and nothing is read from those mods."] = "다른 모드가 설치되어 있으면, 그 모드들이 알려주는 V의 상태입니다. 예: Dark Future의 피로, 허기, 갈증, 신경, 중독. 또한 Equipment-EX 의상이 켜져 있는 동안 V가 눈에 보이게 입고 있는 것도 해당되어, 캐릭터가 가려진 옷이 아니라 그 의상을 이야기합니다.\n\n기본값은 꺼짐입니다. 꺼짐: 아무것도 보내지 않고, 그 모드들에서 아무것도 읽지 않습니다.",
    ["How long it has been since V last talked to this character, in the game and in real days: since last night, or days ago. Said only when the gap is long enough to matter, and not again in the same conversation.\n\nOff: it is not sent, and the mod stops reading the game clock for it."] = "V가 이 캐릭터와 마지막으로 대화한 뒤로 게임 안과 실제 날짜 기준으로 얼마나 지났는지입니다. 어젯밤 이후이거나 며칠 전일 수 있습니다. 간격이 의미 있을 만큼 길 때만 말하고, 같은 대화에서는 다시 말하지 않습니다.\n\n꺼짐: 보내지 않으며, 모드가 이를 위해 게임 시계를 읽지 않습니다.",
    ["Music and TV"] = "음악과 TV",
    ["Other mods’ state"] = "다른 모드의 상태",
    ["Speaks up normally"] = "보통 먼저 말함",
    ["The song playing on the car radio while V rides with the character, or on V’s pocket radio, and what is on a TV near V.\n\nOff: it is not sent, and the mod stops reading it from the game."] = "V가 캐릭터와 차를 타고 갈 때 차 라디오에서 흐르는 노래 또는 V의 휴대용 라디오에서 나오는 노래, 그리고 V 근처 TV에서 나오는 내용입니다.\n\n꺼짐: 아무것도 보내지 않으며, 모드가 게임에서 이를 읽지 않습니다.",
    ["Time since last talk"] = "마지막 대화 이후 지난 시간",
    ["Companions in your party sometimes start talking on their own, at a calm moment or after a scene. With two or more near you, it is often a short chat between up to three of them, and you can join in by talking. Never during fights, scenes, calls or menus.\n\nRarely: about 2 an hour. Normally: about 4. Often (the default): about 6.\n\nWith Johnny speaking up too, the rates add up and they take turns."] = "파티의 동료들은 가끔 스스로 먼저 말을 겁니다. 조용한 순간이나 장면이 끝난 뒤에 가끔 말합니다. 동료 두 명 이상이 근처에 있으면 그중 최대 세 명이 나누는 짧은 대화가 자주 벌어지고, 말을 걸어 대화에 끼어들 수도 있습니다. 전투, 장면, 통화, 메뉴 중에는 절대 말하지 않습니다.\n\n가끔: 플레이 1시간당 약 2번. 보통: 약 4번. 자주 (기본값): 약 6번.\n\nJohnny도 먼저 말할 때는 두 빈도가 더해지고 번갈아 말합니다.",
    ["Johnny Silverhand answers the Talk to Johnny keys, as the voice in V’s head, once the story has him there. Give Talk to Johnny a key on the Key bindings page: none is set by default.\n\nOn: he answers when you talk to him. Rarely: he also speaks up on his own, about 2 an hour. Normally: about 4. Often: about 6.\n\nWith companions speaking up too, the rates add up and they take turns."] = "Johnny Silverhand는 V의 머릿속 목소리로, 이야기가 그를 그곳에 두면 “조니와 대화” 키에 응답합니다. 키 바인딩 페이지에서 “조니와 대화”에 키를 지정하세요. 기본값으로는 설정되어 있지 않습니다.\n\n켜짐: 말을 걸면 응답합니다. 가끔: 스스로도 말합니다. 플레이 1시간당 약 2번. 보통: 약 4번. 자주: 약 6번.\n\n동료도 말할 때는 두 빈도가 더해지고 번갈아 말합니다.",
    ["Choose which live game info the characters are told, such as location, time, weather, company, health, money, gear, quests, music and TV, and other mods’ state.\n\nAll on by default except other mods’ state, which is off. An off kind is not sent to any conversation provider."] = "캐릭터에게 전달할 실시간 게임 정보를 고르세요. 위치, 시간, 날씨, 동료, 체력, 돈, 장비, 퀘스트, 음악과 TV, 다른 모드의 상태 등입니다.\n\n기본적으로 모두 켜져 있지만, 다른 모드의 상태만 꺼져 있습니다. 꺼진 종류는 어떤 대화 제공자에게도 전송되지 않습니다.",
    ["Housemates"] = "동거인",
    ["Housemates talk to each other"] = "동거인끼리 대화",
    ["When two or more housemates are home with you, they talk to each other now and then."] = "동거인이 둘 이상 당신과 함께 집에 있으면 가끔 서로 대화합니다.",
    ["Characters you tell they can stay at your place move into your apartments and live there."] = "당신 집에서 지내도 된다고 말한 캐릭터는 당신의 아파트로 이사해 그곳에서 삽니다.",
    ["Characters you tell they can stay at your place move into your apartments and live there.\n\nOff by default."] = "당신 집에서 지내도 된다고 말한 캐릭터는 당신의 아파트로 이사해 그곳에서 삽니다.\n\n기본값은 꺼짐입니다.",
    ["On: characters you tell they can stay at your place move into your apartments and live there, and you can call them along.\n\nOff: nothing of this runs. Turning it off removes them from your apartments but remembers who lived there, so turning it on brings them back."] = "켜짐: 당신 집에서 지내도 된다고 말한 캐릭터는 당신의 아파트로 이사해 그곳에서 살고, 함께 데려갈 수도 있습니다.\n\n꺼짐: 이 중 아무것도 작동하지 않습니다. 끄면 아파트에서 나가지만 누가 살았는지는 기억하므로, 다시 켜면 돌아옵니다.",
    ["OmniVoice Python"] = "OmniVoice Python",
    ["OmniVoice’s code could not load in it"] = "OmniVoice 코드를 로드할 수 없었습니다",
    ["PyTorch is not installed in it"] = "PyTorch 가 설치되어 있지 않습니다",
    ["Your own Python (omni-python.txt) is being tested. Open this page again in a minute."] = "자신의 Python (omni-python.txt)을 테스트하는 중입니다. 1 분 후 이 페이지를 다시 열어주세요.",
    ["Your own Python (omni-python.txt) is tested when OmniVoice starts or when this page checks again."] = "자신의 Python (omni-python.txt)은 OmniVoice 시작 또는 이 페이지 재확인 시 테스트됩니다.",
    ["Your own Python (omni-python.txt) runs OmniVoice with {backend} on {card}. Experimental."] = "자신의 Python (omni-python.txt)은 {backend}으로 {card}에서 OmniVoice를 실행합니다. 실험적입니다.",
    ["Your own Python (omni-python.txt) was not used: {reason}. OmniVoice uses the Runtime’s Python, which needs an NVIDIA card."] = "자신의 Python (omni-python.txt)은 사용되지 않았습니다: {reason}. OmniVoice는 Runtime의 Python을 사용하며, NVIDIA 카드가 필요합니다.",
    ["a test on the graphics card failed"] = "그래픽 카드 테스트에 실패했습니다",
    ["it did not start or did not answer in time"] = "시작하지 않았거나 시간 내에 응답하지 않았습니다",
    ["its PyTorch finds no graphics card (no CUDA or ROCm)"] = "해당 PyTorch가 그래픽 카드를 찾을 수 없습니다 (CUDA 또는 ROCm 없음)",
    ["the OmniVoice pack is not installed"] = "OmniVoice 팩이 설치되어 있지 않습니다",
    ["the file does not name a python.exe that exists"] = "파일이 존재하는 python.exe를 지정하지 않습니다",
    ["the module {module} is missing in it"] = "모듈 {module}이 없습니다",
    ["1 minute"] = "1 분",
    ["2 people"] = "2 명",
    ["3 people"] = "3 명",
    ["4 people"] = "4 명",
    ["Every character who lives at your place moves out at once, from every apartment. Party members who do not live there are not touched. A housemate who is with you stays in your party."] = "당신의 집에 사는 모든 캐릭터가 모든 아파트에서 한 번에 이사를 나갑니다. 그곳에 살지 않는 파티 멤버는 영향을 받지 않습니다. 당신과 함께하는 동거인은 파티에 남아있습니다.",
    ["Evict"] = "나가게 하기",
    ["Evict all housemates"] = "모든 동거인을 내보내기",
    ["Housemates in one chat"] = "한 채팅에서의 동거인",
    ["Housemates moved out: {count}"] = "동거인이 이사했어요: {count}",
    ["How long the housemates stay quiet after a chat before they may start another. The Companions speak up setting still limits how many chats come in an hour."] = "동거인이 채팅 후 다른 채팅을 시작하기 전에 조용히 있는 시간. 동료가 먼저 말함 설정은 여전히 한 시간에 오는 채팅 수를 제한합니다.",
    ["How many housemates join one chat when that many are home near each other. They speak one at a time. With fewer at home, the chat is as big as it can be."] = "그 많은 동거인이 집에서 서로 가까울 때 한 채팅에 참여하는 동거인의 수. 그들은 한 번에 한 사람씩 말합니다. 집에 있는 사람이 적을수록 채팅은 가능한 한 커집니다.",
    ["Move-in apartment"] = "이사 아파트",
    ["Nobody lives at your place."] = "당신의 집에 아무도 살지 않습니다.",
    ["Pause between chats"] = "채팅 간 일시 중지",
    ["Where a character moves in when you say she can stay but name no apartment and you are not standing in one of yours.\n\nAsk me: she asks which one. Otherwise she takes the apartment you pick here. Only the apartments you own are listed."] = "당신이 그녀가 머물 수 있다고 말하지만 아파트 이름을 지정하지 않고 당신 것 중 하나에 서 있지 않을 때 캐릭터가 이사하는 곳입니다.\n\n나에게 묻기: 그녀가 어느 것인지 묻습니다. 그렇지 않으면 여기서 선택한 아파트를 가집니다. 소유한 아파트만 나열됩니다.",
    ["Ask me"] = "나에게 묻기",
    ["Could not start"] = "시작할 수 없음",
    ["Did not start"] = "시작되지 않음",
    ["If the folder is there, the newest log in red4ext/logs says why RED4ext did not load it: an antivirus that removed a file, or a missing Visual C++ runtime."] = "폴더가 있다면 red4ext/logs의 가장 최근 로그에 RED4ext가 이를 불러오지 않은 이유가 나와 있습니다. 백신이 파일을 삭제했거나 Visual C++ runtime이 없는 경우입니다.",
    ["Load a save first. A key can be set only while a game is loaded."] = "먼저 저장 파일을 불러오세요. 키는 게임이 로드된 상태에서만 설정할 수 있습니다.",
    ["No key press reached the mod, so nothing changed. If keys do not arrive from this menu, set the key in Cyber Engine Tweaks’ Bindings: it works the same."] = "모드에 키 입력이 전달되지 않아서 아무것도 바뀌지 않았습니다. 이 메뉴에서 키가 전달되지 않으면 Cyber Engine Tweaks의 키 바인딩에서 키를 설정하세요. 결과는 같습니다.",
    ["Runtime incomplete"] = "Runtime 불완전",
    ["Runtime not loaded"] = "Runtime 로드되지 않음",
    ["Service not running ({reason})"] = "서비스 실행 중 아님 ({reason})",
    ["The Runtime’s plugin is loaded, but the conversation service left no trace in this session. launcher.log in red4ext/plugins/AiNpcCyberpunkCode says why: launcher.ini switched off, Node missing, or Node blocked by a security program. Fix that, then restart the game."] = "Runtime 플러그인은 로드되었지만 이번 세션에서 대화 서비스의 흔적이 없습니다. red4ext/plugins/AiNpcCyberpunkCode의 launcher.log에 이유가 나와 있습니다. launcher.ini가 꺼져 있거나, Node가 없거나, 보안 프로그램이 Node를 막은 경우입니다. 해결한 다음 게임을 다시 시작하세요.",
    ["The conversation service cannot see this mod’s folder in the game: a mod manager’s virtual folders, or a folder it may not read. Extract the Runtime straight into the Cyberpunk 2077 folder, or start the game from the mod manager that holds the Runtime."] = "대화 서비스가 게임에서 이 모드의 폴더를 보지 못합니다. 모드 관리자의 가상 폴더이거나 읽을 권한이 없는 폴더일 수 있습니다. Runtime을 Cyberpunk 2077 폴더에 바로 풀거나, Runtime이 들어 있는 모드 관리자에서 게임을 시작하세요.",
    ["The conversation service was started and never reported back. A security program probably stopped it at once, or Node cannot run on this PC. Allow red4ext/plugins/AiNpcCyberpunkMod/app/node/node.exe in your security program, then restart the game."] = "대화 서비스가 시작되었지만 응답하지 않았습니다. 보안 프로그램이 바로 중지시켰거나, 이 PC에서 Node를 실행할 수 없을 가능성이 큽니다. 보안 프로그램에서 red4ext/plugins/AiNpcCyberpunkMod/app/node/node.exe를 허용한 다음 게임을 다시 시작하세요.",
    ["Windows would not let the game start the conversation service (error {error}). A security program may be blocking node.exe in red4ext/plugins/AiNpcCyberpunkMod/app/node: allow it, then restart the game."] = "Windows가 게임에서 대화 서비스를 시작하는 것을 허용하지 않았습니다 (오류 {error}). 보안 프로그램이 red4ext/plugins/AiNpcCyberpunkMod/app/node의 node.exe를 막고 있을 수 있습니다. 허용한 다음 게임을 다시 시작하세요.",
    ["Add a server address first."] = "먼저 서버 주소를 추가하세요.",
    ["Asks the server three times who it is and shows whether it is reachable, how long it takes to answer and its version. It sends no speech."] = "서버에 세 번 자신이 누구인지 묻고, 연결 가능 여부, 응답에 걸리는 시간, 버전을 보여 줍니다. 음성은 보내지 않습니다.",
    ["Connected. The server speaks with {voice}."] = "연결됨. 서버가 {voice} 음성으로 말합니다.",
    ["Custom voices"] = "사용자 지정 음성",
    ["Deletes the saved server address. Remote OmniVoice needs one to speak."] = "저장된 서버 주소를 삭제합니다. 원격 OmniVoice가 말하려면 서버 주소가 필요합니다.",
    ["It answers in {ms} ms."] = "{ms} ms 만에 응답합니다.",
    ["Its voice runs on {device}."] = "음성은 {device}에서 실행됩니다.",
    ["Loading"] = "불러오는 중",
    ["Not connected. Replies show as text until the server answers."] = "연결되지 않음. 서버가 응답할 때까지 답변은 텍스트로 표시됩니다.",
    ["Nothing answered at that address. Check that the server is running, that the address and port are right and that both PCs are on the same network. A server started with its default only listens on its own PC: start it with the listen address 0.0.0.0."] = "해당 주소에서 응답이 없습니다. 서버가 실행 중인지, 주소와 포트가 맞는지, 두 PC가 같은 네트워크에 있는지 확인하세요. 기본 설정으로 시작된 서버는 자신의 PC에서만 수신합니다. 수신 주소를 0.0.0.0으로 지정해 시작하세요.",
    ["Off. OmniVoice runs on this PC."] = "꺼짐. OmniVoice는 이 PC에서 실행됩니다.",
    ["On, but no server address is saved. OmniVoice cannot speak yet."] = "켜짐, 하지만 저장된 서버 주소가 없습니다. OmniVoice는 아직 말할 수 없습니다.",
    ["On, but no server address is saved. Pocket is used until you add one."] = "켜짐, 하지만 저장된 서버 주소가 없습니다. 주소를 추가할 때까지 Pocket이 사용됩니다.",
    ["On, but no server address is saved. The server is not used yet."] = "켜짐, 하지만 저장된 서버 주소가 없습니다. 서버는 아직 사용되지 않습니다.",
    ["On, but a cloud voice is chosen under Companion voices, so the server is not used."] = "켜짐, 하지만 동료 음성에서 클라우드 음성이 선택되어 있어 서버는 사용되지 않습니다.",
    ["On. Waiting for the conversation service."] = "켜짐. 대화 서비스를 기다리는 중입니다.",
    ["Paste address"] = "주소 붙여넣기",
    ["Remote OmniVoice"] = "원격 OmniVoice",
    ["Render the voices on another PC or graphics card that runs the OmniVoice server, so this PC keeps its frames.\n\nTurn it on, press Apply and add the server address below. The server then speaks for every Pocket or OmniVoice choice under Companion voices; a cloud voice stays as chosen. If it cannot be reached, replies show as text and the mod retries every few seconds."] = "OmniVoice 서버를 실행하는 다른 PC 또는 그래픽 카드에서 음성을 렌더링하여 이 PC의 프레임을 유지합니다.\n\n켜고 적용을 누른 다음, 아래에 서버 주소를 추가하세요. 서버는 동료 음성에서 Pocket 또는 OmniVoice를 선택한 모든 경우에 말하며, 클라우드 음성은 선택한 대로 유지됩니다. 서버에 연결할 수 없으면 답변은 텍스트로 표시되고, 모드는 몇 초마다 다시 시도합니다.",
    ["Render the OmniVoice voices on another PC or graphics card that runs the OmniVoice server."] = "OmniVoice 서버를 실행하는 다른 PC 또는 그래픽 카드에서 OmniVoice 음성을 렌더링합니다.",
    ["Render Pocket and OmniVoice voices on another PC or graphics card: the on/off switch, the server address and a connection test. It works whichever of those voices is chosen above."] = "Pocket과 OmniVoice 음성을 다른 PC 또는 그래픽 카드에서 렌더링합니다: 켜기/끄기 스위치, 서버 주소, 연결 테스트. 위에서 어느 음성을 선택하든 동작합니다.",
    ["Server address"] = "서버 주소",
    ["Something answered, but it is not the OmniVoice server. Check the port."] = "응답은 있었지만 OmniVoice 서버가 아닙니다. 포트를 확인하세요.",
    ["Start the OmniVoice server on the other PC. Its window shows the address to use, for example 192.168.1.20:8765. Copy it, then choose Paste address. It is read from the clipboard once and saved on this computer.\n\nOn the same PC use 127.0.0.1:8765. You can also write address=192.168.1.20:8765 in player-remote-omnivoice.txt in the conversation service folder.\n\nNothing is sent to it until Remote OmniVoice is on and OmniVoice is chosen, or you press Test."] = "다른 PC에서 OmniVoice 서버를 시작하세요. 서버 창에 사용할 주소(예: 192.168.1.20:8765)가 표시됩니다. 복사한 다음 주소 붙여넣기를 선택하세요. 클립보드에서 한 번 읽어 이 컴퓨터에 저장됩니다.\n\n같은 PC에서는 127.0.0.1:8765를 사용하세요. 대화 서비스 폴더의 player-remote-omnivoice.txt에 address=192.168.1.20:8765라고 적어도 됩니다.\n\n원격 OmniVoice가 켜지고 OmniVoice가 선택되거나 테스트를 누르기 전까지는 아무것도 전송되지 않습니다.",
    ["Status"] = "상태",
    ["The OmniVoice server cannot be reached. Replies show as text until it answers. The mod asks it again every few seconds."] = "OmniVoice 서버에 연결할 수 없습니다. 응답이 올 때까지 답변은 텍스트로 표시됩니다. 모드는 몇 초마다 서버에 다시 요청합니다.",
    ["The clipboard does not hold a server address."] = "클립보드에 서버 주소가 없습니다.",
    ["The clipboard is empty. Copy the address first."] = "클립보드가 비어 있습니다. 먼저 주소를 복사하세요.",
    ["The port must be a number from 1 to 65535."] = "포트는 1에서 65535 사이의 숫자여야 합니다.",
    ["The server address was removed."] = "서버 주소가 삭제되었습니다.",
    ["The server answered but could not load its voice. Its window says why."] = "서버가 응답했지만 음성을 로드하지 못했습니다. 이유는 서버 창에 표시됩니다.",
    ["The server answered but is still loading its voice. Try again in a minute."] = "서버가 응답했지만 아직 음성을 불러오는 중입니다. 1분 후 다시 시도하세요.",
    ["The server is another version. Use the server folder and the mod from the same release."] = "서버 버전이 다릅니다. 같은 릴리스의 서버 폴더와 모드를 사용하세요.",
    ["The server is ready."] = "서버가 준비되었습니다.",
    ["The server refused the request."] = "서버가 요청을 거부했습니다.",
    ["The server took too long to answer."] = "서버 응답이 너무 오래 걸렸습니다.",
    ["Use the address only: no user name, no path, no #."] = "주소만 입력하세요: 사용자 이름, 경로, # 없이.",
    ["Use the address the server window shows, such as 192.168.1.20:8765, without https://."] = "서버 창에 표시된 주소(예: 192.168.1.20:8765)를 https:// 없이 입력하세요.",
    ["Waiting for the server to answer…"] = "서버 응답을 기다리는 중…",
    ["Whether the server is in use right now. It is checked when a voice is needed and again every few seconds after a failure, never while you play."] = "서버가 지금 사용 중인지 여부입니다. 음성이 필요할 때 확인하고, 실패 후에는 몇 초마다 다시 확인합니다. 게임 중에는 확인하지 않습니다.",
    ["Your own character, made in the character editor."] = "캐릭터 편집기에서 만든 내 캐릭터입니다.",
    ["Build for your game"] = "게임용 빌드",
    ["Your game is {game} but the Runtime is the one for game {runtime}. Get the full install zip for game {game} from the mod’s Nexus Mods page (main file for game 2.5, optional file for game 2.31) and extract it into the Cyberpunk 2077 folder over this one, then restart the game."] = "게임은 {game}이지만 Runtime은 게임 {runtime}용입니다. 모드의 Nexus Mods 페이지(메인 파일은 게임 2.5용, 선택 파일은 게임 2.31용)에서 게임 {game}용 전체 설치 zip을 받아 Cyberpunk 2077 폴더에 기존 파일 위로 풀고 게임을 다시 시작하세요.",
    ["Your game is {game} but the Scripts are the build for game {scripts}. Get the update zip for game {game} from the mod’s Nexus Mods page (the update file is for game 2.5, the optional update file for game 2.31) and install it over these, then restart the game."] = "게임은 {game}이지만 Scripts는 게임 {scripts}용 빌드입니다. 모드의 Nexus Mods 페이지(업데이트 파일은 게임 2.5용, 선택 업데이트 파일은 게임 2.31용)에서 게임 {game}용 업데이트 zip을 받아 기존 파일 위에 설치한 다음 게임을 다시 시작하세요.",
    ["Your game is {game} but the Scripts and the Runtime are the build for game {scripts}. Get the full install zip for game {game} from the mod’s Nexus Mods page (main file for game 2.5, optional file for game 2.31) and extract it into the Cyberpunk 2077 folder over these, then restart the game."] = "게임은 {game}이지만 Scripts와 Runtime은 게임 {scripts}용 빌드입니다. 모드의 Nexus Mods 페이지(메인 파일은 게임 2.5용, 선택 파일은 게임 2.31용)에서 게임 {game}용 전체 설치 zip을 받아 기존 파일 위로 Cyberpunk 2077 폴더에 풀고 게임을 다시 시작하세요.",
    ["The Scripts are the build for game {scripts} but the Runtime is the build for game {runtime}, and the game version matches neither. Extract the full install zip made for the same game as yours (from Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "Scripts는 게임 {scripts}용 빌드이고 Runtime은 게임 {runtime}용 빌드이며, 게임 버전은 둘 중 어느 것과도 맞지 않습니다. 내 게임과 같은 게임용으로 만든 전체 설치 zip(Nexus Mods에서)을 Cyberpunk 2077 폴더에 풀고 게임을 다시 시작하세요.",
    ["The Runtime is for game {other}, yours is {game}. Get the full install zip for {game}."] = "Runtime은 게임 {other}용이고 현재 게임은 {game}입니다. {game}용 전체 설치 ZIP을 받으세요.",
    ["The Scripts are for game {other}, yours is {game}. Get the update zip for {game}."] = "Scripts는 게임 {other}용이고 현재 게임은 {game}입니다. {game}용 업데이트 ZIP을 받으세요.",
    ["This mod is for game {other}, yours is {game}. Get the full install zip for {game}."] = "이 모드는 게임 {other}용이고 현재 게임은 {game}입니다. {game}용 전체 설치 ZIP을 받으세요.",
    ["Scripts are for game {scripts}, Runtime for {runtime}. They must match. See Help in Settings."] = "Scripts는 {scripts}용, Runtime은 {runtime}용입니다. 서로 맞아야 합니다. 설정의 도움말 참조.",
    ["Choose one of the listed microphones."] = "목록에 있는 마이크 중 하나를 고르세요.",
    ["Microphone"] = "마이크",
    ["The microphone you chose in Settings ({chosen}) is not connected, so the Windows default input is used: {name}."] = "설정에서 고른 마이크({chosen})가 연결되어 있지 않아 Windows 기본 입력을 사용합니다: {name}.",
    ["The microphone you chose in Settings is not connected, so the Windows default input is used."] = "설정에서 고른 마이크가 연결되어 있지 않아 Windows 기본 입력을 사용합니다.",
    ["Windows default"] = "Windows 기본값",
    ["not connected"] = "연결 안 됨",
    ["{name}, chosen in Settings > Voices."] = "{name}, 설정 > 음성에서 선택됨.",
    ["{name}, the Windows default input. Settings > Voices > Microphone chooses another."] = "{name}, Windows 기본 입력. 다른 입력은 설정 > 음성 > 마이크에서 고를 수 있습니다.",
    ["Gameplay"] = "게임플레이",
    ["Revenge ambushes"] = "복수 매복",
    ["A gang you keep killing may rarely send a small squad after you, with a short threat to shout. A long wait follows each one.\n\nNever in a fight, scene, call, vehicle, indoors, safe zone or while wanted. The threats need Talk to ordinary NPCs."] = "계속해서 죽이는 갱단이 드물게 짧은 위협과 함께 소규모 무리를 보낼 수 있어요. 한 번 뒤에는 오랜 대기 시간이 있어요.\n\n전투, 장면, 통화, 차량 안, 실내, 안전 구역, 수배 중에는 절대 나타나지 않아요. 위협에는 “일반 NPC와 대화”가 필요해요.",
    ["Speak dialogue choices"] = "대화 선택지 말하기",
    ["Say a dialogue choice to pick it: its words, a part of them, or its number (\"two\", \"the last one\"). If nothing fits clearly, nothing is picked. No character answers.\n\nPresses the arrow keys and Enter, so the game must be in front. Needs speech recognition on this PC. Headphones work best."] = "대화 선택지를 말하면 고를 수 있습니다. 선택지의 단어, 일부 단어, 또는 번호(\"둘\", \"마지막 것\")로 말하면 됩니다. 어떤 선택지에도 분명히 맞지 않으면 아무것도 고르지 않습니다. 어떤 캐릭터도 응답하지 않습니다.\n\n방향키와 Enter를 누르므로 게임이 맨 앞에 있어야 합니다. 이 PC에서 음성 인식이 필요합니다. 헤드폰을 쓰면 가장 잘 작동합니다.",
    ["No option matched. Say its number."] = "일치하는 선택지가 없습니다. 번호를 말하세요.",
    ["Two options fit. Say its number."] = "두 개의 선택지가 맞습니다. 번호를 말하세요.",
    ["Speaking a choice needs speech recognition on this PC."] = "선택지를 말하려면 이 PC에서 음성 인식이 필요합니다.",
    ["AMD’s ROCm PyTorch does not support this card yet."] = "AMD의 ROCm PyTorch는 아직 이 카드를 지원하지 않습니다.",
    ["Another setup is already running. Wait for it to finish."] = "다른 설치 작업이 이미 실행 중입니다. 끝날 때까지 기다려 주세요.",
    ["Cancelled"] = "취소했습니다",
    ["Cancelling…"] = "취소하는 중…",
    ["Checking your card…"] = "카드를 확인하는 중…",
    ["Downloading {done} of {total} MB ({percent}%)"] = "{done} / {total} MB 다운로드 중 ({percent}%)",
    ["Downloading…"] = "다운로드 중…",
    ["Experimental. Pocket speaks until it is ready. A local voice never switches to a cloud voice."] = "실험적 기능입니다. Pocket은 준비될 때까지 음성을 냅니다. 로컬 음성은 클라우드 음성으로 바뀌지 않습니다.",
    ["Frees about {disk} GB."] = "약 {disk} GB가 확보됩니다.",
    ["Frees the space it took."] = "사용하던 공간을 되돌려 줍니다.",
    ["Install"] = "설치",
    ["Installed"] = "설치됨",
    ["Installed. OmniVoice uses it when it starts."] = "설치됨. 시작할 때 OmniVoice가 사용합니다.",
    ["It is kept in the mod’s data folder on drive C:."] = "C: 드라이브의 모드 데이터 폴더에 보관됩니다.",
    ["It runs in the background while you play. The game keeps running and nothing else changes."] = "플레이하는 동안 백그라운드에서 실행됩니다. 게임은 계속 실행되며 다른 것은 바뀌지 않습니다.",
    ["It takes about {disk} GB on drive C: in the mod’s data folder."] = "C: 드라이브의 모드 데이터 폴더에 약 {disk} GB를 사용합니다.",
    ["MIOpen convolutions (AMD)"] = "MIOpen 컨볼루션(AMD)",
    ["Not available on this PC. It needs an AMD Radeon card and the OmniVoice pack."] = "이 PC에서는 사용할 수 없습니다. AMD Radeon 카드와 OmniVoice 팩이 필요합니다.",
    ["OmniVoice for AMD"] = "AMD용 OmniVoice",
    ["OmniVoice on AMD: set up first"] = "AMD의 OmniVoice: 먼저 설정하세요",
    ["OmniVoice then no longer starts on this card until it is set up again."] = "그러면 이 카드에서 OmniVoice가 다시 설정하기 전까지 시작되지 않습니다.",
    ["On: AMD’s MIOpen runs the convolutions, with MIOPEN_FIND_MODE=2 and MIOPEN_FIND_ENFORCE=1. Off: PyTorch’s own convolutions. Which is faster depends on your card and driver: if voices are slow or stop part-way, try the other one. AMD cards only. OmniVoice restarts with the new choice when it is idle."] = "켜기: AMD의 MIOpen이 컨볼루션을 실행합니다(MIOPEN_FIND_MODE=2, MIOPEN_FIND_ENFORCE=1). 끄기: PyTorch 자체 컨볼루션. 어느 쪽이 빠른지는 카드와 드라이버에 따라 다릅니다. 음성이 느리거나 중간에 멈추면 다른 쪽을 시도해 보세요. AMD 카드에서만 사용합니다. OmniVoice는 한가할 때 새 설정으로 다시 시작합니다.",
    ["Own Python"] = "직접 설치한 Python",
    ["Ready"] = "준비됨",
    ["Ready. OmniVoice runs on {card} with AMD’s ROCm."] = "준비됨. OmniVoice는 AMD의 ROCm으로 {card}에서 실행됩니다.",
    ["Reinstall"] = "다시 설치",
    ["Remove AMD setup"] = "AMD 설치 제거",
    ["Removing the AMD setup…"] = "AMD 설치를 제거하는 중…",
    ["Run OmniVoice on your AMD Radeon card with AMD’s ROCm: one download, set up from here."] = "AMD Radeon 카드에서 AMD의 ROCm으로 OmniVoice를 실행하세요. 한 번만 내려받고 여기서 설정합니다.",
    ["Set up OmniVoice for AMD"] = "AMD용 OmniVoice 설정하기",
    ["Starting the AMD setup…"] = "AMD 설치를 시작하는 중…",
    ["Testing it on your card…"] = "카드에서 테스트하는 중…",
    ["The AMD setup was removed."] = "AMD 설치가 제거되었습니다.",
    ["The OmniVoice pack is not installed. Install it first."] = "OmniVoice 팩이 설치되어 있지 않습니다. 먼저 설치하세요.",
    ["The conversation service is not running. Restart the game."] = "대화 서비스가 실행되고 있지 않습니다. 게임을 다시 시작하세요.",
    ["The download did not finish. Check your connection and try again."] = "다운로드가 끝나지 않았습니다. 연결을 확인하고 다시 시도하세요.",
    ["The download is not ready yet in this version of the mod."] = "이 버전의 모드에서는 아직 다운로드를 사용할 수 없습니다.",
    ["The downloaded files did not check out. Try again."] = "내려받은 파일이 확인되지 않았습니다. 다시 시도하세요.",
    ["The files could not be unpacked. Try again."] = "파일의 압축을 풀 수 없습니다. 다시 시도하세요.",
    ["The setup did not finish. Try again."] = "설치가 끝나지 않았습니다. 다시 시도하세요.",
    ["The setup did not pass the test on your card, so OmniVoice cannot use it."] = "설치가 카드 테스트를 통과하지 못해서 OmniVoice가 사용할 수 없습니다.",
    ["The setup is installed but did not pass the test on your card. Choose Reinstall."] = "설치는 되었지만 카드 테스트를 통과하지 못했습니다. 다시 설치를 선택하세요.",
    ["There is not enough free space on drive C:. Free some up and try again."] = "C: 드라이브의 여유 공간이 부족합니다. 공간을 확보하고 다시 시도하세요.",
    ["This PC has no AMD Radeon card this setup can use."] = "이 PC에는 이 설치에서 쓸 수 있는 AMD Radeon 카드가 없습니다.",
    ["Unpacking…"] = "압축 푸는 중…",
    ["Your own Python (omni-python.txt) is used instead. Delete that file to use this setup."] = "대신 직접 설치한 Python(omni-python.txt)이 사용됩니다. 이 설치를 사용하려면 그 파일을 삭제하세요.",
    ["your AMD card"] = "AMD 카드",
    ["{voice} · AMD: set up first"] = "{voice} · AMD: 먼저 설정하세요",
    ["The AMD setup (Settings > Voices > OmniVoice for AMD) runs OmniVoice with ROCm on {card}. Experimental."] = "AMD 설정(설정 > 음성 > AMD용 OmniVoice)이 {card}에서 ROCm으로 OmniVoice를 실행합니다. 실험적 기능입니다.",
    ["The AMD setup was not used: {reason}. Choose Reinstall in Settings > Voices > OmniVoice for AMD. Until then Pocket speaks."] = "AMD 설정이 사용되지 않았습니다: {reason}. 설정 > 음성 > AMD용 OmniVoice에서 다시 설치를 선택하세요. 그때까지는 Pocket이 말합니다.",
    ["Borrow eddies from your characters, lend them eddies and pay each other back, by talking. Each character has money of their own, as their story has it, and decides by how they feel about you. Now and then they ask you for a loan.\n\nEddies change hands as soon as a character agrees, and only with your own characters (party, invited visitors, housemates). The game’s own characters only talk about it. Off by default."] = "대화를 통해 캐릭터에게 에디를 빌리고, 에디를 빌려주고, 서로 갚을 수 있습니다. 각 캐릭터는 자신의 이야기에 따른 자신만의 돈을 가지고 있으며, 당신에 대한 감정에 따라 결정합니다. 가끔 캐릭터가 돈을 빌려 달라고 부탁하기도 합니다.\n\n캐릭터가 동의하는 즉시 에디가 주인을 바꾸며, 이는 당신의 캐릭터(파티원, 초대한 방문객, 룸메이트)와 주고받을 때만 일어납니다. 게임의 캐릭터들은 그것에 대해 말만 합니다. 기본값은 꺼짐입니다.",
    ["Eddies with characters"] = "캐릭터와 에디",
    ["The eddies could not be moved."] = "에디를 옮길 수 없었습니다.",
    ["You do not have enough eddies for that."] = "그렇게 하기에는 에디가 부족합니다.",
    ["{name} is no longer with you, so no eddies moved."] = "{name} 캐릭터가 더 이상 함께하지 않아 에디가 옮겨지지 않았습니다.",
    ["Add to favorites"] = "즐겨찾기에 추가",
    ["One download of about {size} GB."] = "약 {size} GB를 한 번 내려받습니다.",
    ["One download."] = "한 번 내려받습니다.",
    ["Remove from favorites"] = "즐겨찾기에서 제거",
    ["Set up OmniVoice on your AMD Radeon card with one download, and choose how it runs."] = "한 번만 내려받아 AMD Radeon 카드에 OmniVoice를 설정하고, 실행 방식을 고르세요.",
    ["That entry cannot be a favorite."] = "그 항목은 즐겨찾기에 추가할 수 없습니다.",
    ["You have too many favorites. Remove one first."] = "즐겨찾기가 너무 많습니다. 먼저 하나를 제거하세요.",
    ["Your AMD Radeon card ({card}) can run OmniVoice. Set it up in Settings > Voices > OmniVoice for AMD: one download, then it starts by itself."] = "AMD Radeon 카드({card})에서 OmniVoice를 실행할 수 있습니다. 설정 > 음성 > AMD용 OmniVoice에서 설정하세요. 한 번 내려받으면 그 뒤로는 저절로 시작됩니다.",
    ["Your AMD Radeon card can run OmniVoice. Set it up in Settings > Voices > OmniVoice for AMD: one download, then it starts by itself. Until then Pocket speaks."] = "AMD Radeon 카드에서 OmniVoice를 실행할 수 있습니다. 설정 > 음성 > AMD용 OmniVoice에서 설정하세요. 한 번 내려받으면 그 뒤로는 저절로 시작됩니다. 그때까지는 Pocket이 음성을 냅니다.",
    ["Your favorites could not be saved, so they last only until the game closes."] = "즐겨찾기를 저장할 수 없어서, 게임을 닫을 때까지만 유지됩니다.",
    ["{count} matching characters"] = "일치하는 캐릭터 {count}명",
    ["{name} is no longer a favorite."] = "{name}은(는) 더 이상 즐겨찾기가 아닙니다.",
    ["After you speak (hold to talk or Voice activation), V says your words out loud in V’s voice, and the reply follows V’s line. Off by default, because you just said it yourself.\n\nThis works on its own, whether or not typed lines are spoken. The choices are the same as for typed lines, and V speaks with one engine: choosing one here changes it for typed lines too, unless those are Off."] = "말하기(누르고 말하기 또는 음성 활성화) 후 V가 당신의 말을 V의 음성으로 크게 따라 말하고, 응답은 V의 대사에 이어집니다. 당신이 직접 말한 내용이므로 기본값은 꺼짐입니다.\n\n이는 입력한 대사를 소리 내어 읽는지와 관계없이 단독으로 작동합니다. 선택 항목은 입력한 대사와 같고, V는 하나의 엔진으로 말합니다. 여기서 선택하면 입력한 대사가 꺼짐이 아닌 한 입력한 대사에도 적용됩니다.",
    ["Off: no subtitles.\n\nCinematic subtitles: the game’s regular dialogue subtitles.\n\nAbove the speaker: over the companion who is talking.\n\nWith Companion voices Off as well, automatic reactions stay silent."] = "꺼짐: 자막 없음.\n\n시네마틱 자막: 게임의 일반 대화 자막.\n\n말하는 사람 위: 말하고 있는 동료 위에 표시.\n\n동료 음성도 꺼짐이면 자동 반응은 계속 무음입니다.",
    ["Set from the start: F7 talk by voice, F6 talk by text, F10 group voice chat, F8 group text chat and F4 the Companion Manager. Clear one and it stays clear. Restore defaults brings them back."] = "처음부터 설정됨: F7 음성으로 대화, F6 텍스트로 대화, F10 그룹 음성 채팅, F8 그룹 텍스트 채팅, F4 동료 관리. 하나를 지우기로 비우면 그대로 비어 있습니다. 기본값 복원을 누르면 다시 돌아옵니다.",
    ["The input the mod listens to for the talk keys and Voice activation.\n\nWindows default follows the input Windows picks. Choose another if the default never hears you, for example when a mixer app routes your microphone elsewhere.\n\nA change counts the next time the microphone opens. A missing input falls back to the default."] = "모드가 대화 키와 음성 활성화를 위해 듣는 입력입니다.\n\nWindows 기본값은 Windows가 선택한 입력을 따릅니다. 기본값으로 전혀 듣지 못하는 경우(예: 믹서 앱이 마이크를 다른 곳으로 보내는 경우)에는 다른 입력을 선택하세요.\n\n변경 사항은 다음에 마이크가 열릴 때 적용됩니다. 입력이 없으면 기본값으로 대체됩니다.",
    ["The language the characters speak. Counts only while Companion voices is not Off; with it Off, replies follow what you write.\n\nAutomatic: follows what you write or say, and never changes on a short line.\n\nA voice that cannot speak the language shows the reply as text."] = "캐릭터가 말하는 언어입니다. 동료 음성이 꺼짐이 아닐 때만 적용되며, 꺼짐이면 응답이 입력한 내용을 따릅니다.\n\n자동: 입력하거나 말한 내용을 따르며, 짧은 대사에서는 바뀌지 않습니다.\n\n해당 언어를 말할 수 없는 음성은 응답을 텍스트로 표시합니다.",
    ["V’s typed and microphone lines use the same voice. Choose the same one for both, or Off for one."] = "V의 입력 대사와 마이크 대사는 같은 음성을 사용합니다. 둘 다 같은 음성을 고르거나, 한쪽을 꺼짐으로 설정하세요.",
    ["V’s voice for microphone lines"] = "마이크로 입력한 대사의 V 음성",
    ["A saved party holds {count} characters, so the rest were left out."] = "저장된 파티에는 캐릭터가 {count}명까지만 들어가므로 나머지는 제외되었습니다.",
    ["Already with you: {names}."] = "이미 함께 있습니다: {names}.",
    ["Another saved party already has that name."] = "같은 이름의 다른 저장된 파티가 이미 있습니다.",
    ["Could not invite: {names}."] = "초대할 수 없습니다: {names}.",
    ["Deletes this saved party. The characters in your party now are not touched."] = "이 저장된 파티를 삭제합니다. 지금 파티에 있는 캐릭터는 영향을 받지 않습니다.",
    ["Invites the characters of this party to your side: {names}.\n\nIt adds to your party and dismisses nobody. A character who is already with you is not invited twice. Anyone who cannot come is named, with the reason."] = "이 파티의 캐릭터들을 내 곁으로 초대합니다: {names}.\n\n현재 파티에 추가되며 아무도 해산되지 않습니다. 이미 함께 있는 캐릭터는 두 번 초대되지 않습니다. 올 수 없는 캐릭터는 이유와 함께 표시됩니다.",
    ["Parties"] = "파티",
    ["Party"] = "파티",
    ["Press Delete again to delete {name}."] = "{name}을(를) 삭제하려면 삭제를 한 번 더 누르세요.",
    ["Press again"] = "다시 누르기",
    ["Press again to delete this saved party. Anything else cancels."] = "이 저장된 파티를 삭제하려면 한 번 더 누르세요. 다른 입력은 취소됩니다.",
    ["Rename"] = "이름 변경",
    ["Rename party"] = "파티 이름 변경",
    ["Renamed to {name}."] = "{name}(으)로 이름을 변경했습니다.",
    ["Replaces the characters of this saved party with the ones in your party now."] = "이 저장된 파티의 캐릭터를 지금 파티에 있는 캐릭터로 바꿉니다.",
    ["Save current party"] = "현재 파티 저장",
    ["Saved as {name}. Press Spawn party under it to invite them again."] = "{name}(으)로 저장했습니다. 그 아래 파티 초대를 누르면 다시 초대됩니다.",
    ["Saved party: {name}"] = "저장된 파티: {name}",
    ["Saves the characters in your party now, copies and your own characters included, as a party you can invite again with one press. It is named Party 1, Party 2 and so on, and appears below.\n\nYou keep up to {count} saved parties."] = "지금 파티에 있는 캐릭터(복사본과 직접 만든 캐릭터 포함)를 한 번의 누름으로 다시 초대할 수 있는 파티로 저장합니다. 이름은 파티 1, 파티 2 등으로 붙으며 아래에 표시됩니다.\n\n저장된 파티는 최대 {count}개까지 보관할 수 있습니다.",
    ["Spawn"] = "초대",
    ["Spawn party"] = "파티 초대",
    ["That party no longer exists."] = "그 파티는 더 이상 존재하지 않습니다.",
    ["The characters of this party: {names}."] = "이 파티의 캐릭터: {names}.",
    ["The party could not be saved."] = "파티를 저장할 수 없습니다.",
    ["This menu has no text box, so the party keeps its name. Mod Configuration Menu has one: type the name in its Search box."] = "이 메뉴에는 텍스트 입력란이 없어 파티는 이름을 유지합니다. Mod Configuration Menu에는 입력란이 있으니 검색창에 이름을 입력하세요.",
    ["Type the new name in the Search box at the top (Mod Configuration Menu), then press Rename. Native Settings UI has no text box, so a party keeps its name there."] = "상단 검색창(Mod Configuration Menu)에 새 이름을 입력한 다음 이름 변경을 누르세요. Native Settings UI에는 텍스트 입력란이 없어 그곳에서는 파티가 이름을 유지합니다.",
    ["Type the new name in the Search box first, then press Rename."] = "먼저 검색창에 새 이름을 입력한 다음 이름 변경을 누르세요.",
    ["Update"] = "업데이트",
    ["Update with current party"] = "현재 파티로 업데이트",
    ["You can keep {count} saved parties. Delete one first."] = "저장된 파티는 {count}개까지 보관할 수 있습니다. 먼저 하나를 삭제하세요.",
    ["Your party is empty. Invite someone first."] = "파티가 비어 있습니다. 먼저 누군가를 초대하세요.",
    ["Your saved parties could not be written to disk, so they last only until the game closes."] = "저장된 파티를 디스크에 쓸 수 없어 게임을 종료할 때까지만 유지됩니다.",
    ["that character model is unavailable"] = "해당 캐릭터 모델을 사용할 수 없음",
    ["the invitation was refused"] = "초대가 거절됨",
    ["{name} ({count})"] = "{name} ({count})",
    ["{name} ({reason})"] = "{name} ({reason})",
    ["{name} deleted."] = "{name}이(가) 삭제되었습니다.",
    ["{name} has nobody to invite."] = "{name}에게 초대할 사람이 없습니다.",
    ["{name} now has the characters of your party."] = "{name}에 이제 파티의 캐릭터가 있습니다.",
    ["{party}: inviting {names}."] = "{party}: {names} 초대 중.",
    ["Adds {name} to your favorites. They are listed at the top of page 1, and first in the phone’s Chat tab. Updates never touch them."] = "{name}을(를) 즐겨찾기에 추가합니다. 1페이지 맨 위와 휴대폰 채팅 탭 맨 앞에 표시되며, 업데이트해도 바뀌지 않습니다.",
    ["Favorites"] = "즐겨찾기",
    ["Only the first {count} favorites are listed here. The others are in the list below."] = "여기에는 처음 {count}개의 즐겨찾기만 표시됩니다. 나머지는 아래 목록에 있습니다.",
    ["Page {page} of {pages}: {kind} {first} to {last}."] = "{page}/{pages} 페이지: {kind} {first}~{last}.",
    ["Press to go to page {page} of {pages}: {kind} {first} to {last}."] = "누르면 {page}/{pages} 페이지로 이동합니다: {kind} {first}~{last}.",
    ["Takes {name} out of your favorites. Her place in the list below stays."] = "{name}을(를) 즐겨찾기에서 제외합니다. 아래 목록의 위치는 그대로 유지됩니다.",
    ["This is the first page."] = "첫 페이지입니다.",
    ["This is the last page."] = "마지막 페이지입니다.",
    ["characters"] = "캐릭터",
    ["entries"] = "항목",
    ["models"] = "모델",
    ["{count} more favorites"] = "즐겨찾기 {count}개 더",
    ["{name} is now a favorite. Favorites are at the top of page 1."] = "{name}을(를) 즐겨찾기에 추가했습니다. 즐겨찾기는 1페이지 맨 위에 표시됩니다.",
    ["Favorite"] = "즐겨찾기",
    -- Look and moves part of the character editor (docs/CHARACTER_EDITOR.md)
    ["That look is not one of this character’s."] = "그 룩은 이 캐릭터의 것이 아닙니다.",
    ["That choice is not available."] = "그 선택은 사용할 수 없습니다.",
    ["The editor keeps choices for {max} characters. Reset one first."] = "편집기는 최대 {max}명의 캐릭터에 대한 선택만 저장합니다. 먼저 하나를 재설정하세요.",
    ["Usual look"] = "평소 룩",
    ["Home clothes: tank top, boxer shorts, flip-flops"] = "집에서 입는 옷: 민소매 티, 트렁크, 슬리퍼",
    ["No jacket"] = "재킷 없음",
    ["No jacket and harness"] = "재킷 없음, 하네스 착용",
    ["Home clothes: shirt and trousers"] = "집에서 입는 옷: 셔츠와 바지",
    ["Home clothes: tank top and trousers"] = "집에서 입는 옷: 민소매 티와 바지",
    ["Hooded jacket"] = "후드 재킷",
    ["Home clothes: t-shirt and trousers"] = "집에서 입는 옷: 티셔츠와 바지",
    ["Collar down"] = "칼라 내림",
    ["Valentino look"] = "발렌티노 룩",
    ["Suit"] = "정장",
    ["Club night, no jacket"] = "클럽 나이트, 재킷 없음",
    ["Solo look"] = "솔로 룩",
    ["Date night"] = "데이트 나이트",
    ["T-shirt"] = "티셔츠",
    ["Vest"] = "조끼",
    ["Paradise look"] = "파라다이스 룩",
    ["Bartender"] = "바텐더",
    ["Dress without the fur coat"] = "퍼 코트 없이 드레스",
    ["Trench coat"] = "트렌치코트",
    ["Without the coat"] = "코트 없이",
    ["CEO look with coat"] = "CEO 룩, 코트 착용",
    ["CEO look"] = "CEO 룩",
    ["Pyjamas"] = "잠옷",
    ["Go back to the usual look and moves for {name}? Your choices on this part are removed."] = "{name}의 평소 룩과 동작으로 되돌릴까요? 이 부분에서 선택한 내용은 삭제됩니다.",
    ["Back to the usual look and moves."] = "평소 룩과 동작으로 되돌렸습니다.",
    ["Choices for how this character looks and moves. They work with every conversation option, Convai included, except the reply length."] = "이 캐릭터의 외형과 동작에 대한 선택입니다. Convai를 포함한 모든 대화 옵션에서 작동하며, 응답 길이만 예외입니다.",
    ["Outfit"] = "의상",
    ["Automatic follows the “Companions change outfits” setting in the game: day and night looks, now and then a change, and casual clothes at home. A look you pick is worn all the time. Only your own companions and residents are dressed, and they change while nobody is looking. Characters the game places are never changed."] = "자동은 게임의 “동료 의상 변경” 설정을 따릅니다. 낮과 밤 룩, 가끔 바뀌는 의상, 집에서 입는 편한 옷이 적용됩니다. 직접 고른 룩은 항상 유지됩니다. 나의 동료와 주민만 옷을 갈아입으며, 아무도 보지 않을 때 바뀝니다. 게임이 배치한 캐릭터는 절대 바뀌지 않습니다.",
    ["This character has only one look in the game files, so there is no outfit to choose."] = "이 캐릭터는 게임 파일에 룩이 하나뿐이라 고를 의상이 없습니다.",
    ["Talking gestures"] = "대화 중 제스처",
    ["How the hands move while they speak a longer reply."] = "길게 응답할 때 손이 움직이는 방식입니다.",
    ["Normal"] = "보통",
    ["Calm: smaller gestures, not as often"] = "차분함: 작은 제스처, 덜 자주",
    ["Lively: bigger gestures, more often"] = "활발함: 큰 제스처, 더 자주",
    ["None: the hands stay at rest"] = "없음: 손을 가만히 둡니다",
    ["Nod while you talk to them"] = "대화할 때 고개 끄덕이기",
    ["A small nod now and then while you speak."] = "말하는 동안 가끔 작게 고개를 끄덕입니다.",
    ["Idle moves"] = "대기 동작",
    ["What they do now and then while they stand beside you."] = "곁에 서 있을 때 가끔 하는 동작입니다.",
    ["Plain stances only, no props like a cup or a cigarette"] = "단순한 자세만, 컵이나 담배 같은 소품은 없음",
    ["None: they keep the stance they have"] = "없음: 지금의 자세를 유지합니다",
    ["Sit down and take a place"] = "앉아서 자리 잡기",
    ["Takes a seat beside you when you sit, and a seat or a spot in your flat at home. Switched off, they stay on their feet beside you."] = "당신이 앉으면 옆에 앉고, 당신의 아파트에서는 자리나 지정된 장소에 앉습니다. 끄면 옆에 서 있습니다.",
    ["Comment on fights and loot"] = "전투와 전리품에 대해 말하기",
    ["Switched off, they say nothing about fights or about what you pick up."] = "끄면 전투나 주운 물건에 대해 아무 말도 하지 않습니다.",
    ["Reply length"] = "응답 길이",
    ["Shorter: up to about {words} words"] = "짧게: 약 {words}단어까지",
    ["Very short: up to about {words} words"] = "아주 짧게: 약 {words}단어까지",
    ["A saved choice counts within a few seconds. Clothes change when nobody is looking."] = "저장한 선택은 몇 초 안에 적용됩니다. 옷은 아무도 보지 않을 때 바뀝니다.",
    ["Look and moves"] = "룩과 동작",
    ["Shift"] = "Shift",
    ["Ctrl"] = "Ctrl",
    ["Alt"] = "Alt",
    ["Hold Shift, Ctrl or Alt while you press a key to set a combination such as Shift+F5. A combination runs only with exactly those keys held, and a plain key does not run while one is held. In the game Shift sprints, Ctrl dodges and Alt opens the weapon wheel, so V does that too."] = "키를 누를 때 Shift, Ctrl 또는 Alt를 함께 누르고 있으면 Shift+F5 같은 조합을 설정할 수 있습니다. 조합은 정확히 그 키들을 누르고 있을 때만 작동하고, 단독 키는 그중 하나를 누르고 있으면 작동하지 않습니다. 게임에서는 Shift는 질주, Ctrl은 회피, Alt는 무기 휠 열기에 쓰이므로 V도 그 동작을 합니다.",
    ["Disk space"] = "디스크 공간",
    ["Your {drive} drive is almost full ({free} GB free). Free space so the mod can save logs and memories."] = "{drive} 드라이브의 여유 공간이 거의 없어요 ({free} GB 남음). 로그와 기억 저장 공간을 확보하세요.",
    ["An input marked (!) looks like a loopback or virtual input, such as Stereo Mix, CABLE Output or a mixer’s Out. It can carry other apps’ sound, for example the far side of a call, so the mod never picks one by itself."] = "(!) 표시가 붙은 입력은 Stereo Mix, CABLE Output, 믹서의 출력 같은 루프백 또는 가상 입력처럼 보입니다. 통화 상대의 목소리처럼 다른 앱의 소리도 담길 수 있어서, 모드가 혼자서 고르는 일은 없습니다.",
    ["The input you chose looks like it carries PC sound, not only your voice. If characters hear your calls, choose your real microphone."] = "고른 입력에 목소리뿐 아니라 PC 소리도 담기는 것으로 보입니다. 캐릭터들이 내 통화를 듣고 있다면 실제 마이크를 골라 주세요.",
    ["{name} looks like it carries PC sound, such as a call, not only your voice. Choose your real microphone in Settings > Voices > Microphone."] = "{name}에는 목소리뿐 아니라 통화 같은 PC 소리도 담기는 것으로 보입니다. 설정 > 음성 > 마이크에서 실제 마이크를 골라 주세요.",
    ["Companions can see"] = "동료의 시야",
    ["Each line also gets a recent picture of your surroundings, taken from the game window just before you talk. Works with every conversation provider. Local AI needs a model that can see. A model that cannot just gets your words.\n\nOnly the game window, only while someone is near, kept briefly in memory. Off means nothing is captured."] = "각 대사에는 말하기 직전 게임 창에서 찍은 주변의 최근 화면도 함께 전달됩니다. 모든 대화 제공자와 함께 작동합니다. Local AI에는 화면을 볼 수 있는 모델이 필요합니다. 볼 수 없는 모델은 말만 받습니다.\n\n게임 창만, 누군가 근처에 있을 때만, 잠시 메모리에 보관됩니다. 끄면 아무것도 캡처되지 않습니다.",
    ["The yellow border is Windows showing a capture. Turn off Companions can see to stop it."] = "노란 테두리는 Windows 화면 캡처 표시입니다. 동료의 시야를 끄면 꺼집니다.",
    ["This Local AI model cannot see pictures, so replies use only your words."] = "이 Local AI 모델은 사진을 볼 수 없어서 응답에는 플레이어의 말만 사용됩니다.",
    ["This model can see pictures with its vision file, from {folder}/vision on Hugging Face."] = "Hugging Face {folder}/vision의 vision 파일을 설치하면 이 모델이 사진을 볼 수 있습니다.",
    ["Your Custom endpoint does not accept pictures, so replies use only your words."] = "Custom 엔드포인트가 사진을 받지 않아서 응답에는 플레이어의 말만 사용됩니다.",
    ["No API key is saved yet. Copy your key from your provider, press Paste API key, then test again."] = "아직 저장된 API 키가 없습니다. 제공자에서 키를 복사한 다음 API 키 붙여넣기를 누르고 다시 테스트하세요.",
    ["Add"] = "추가",
    ["Deletes this free setup: the endpoint URL, the model ID and the API key saved with it."] = "저장된 이 무료 설정(엔드포인트 URL, 모델 ID, 함께 저장된 API 키)을 삭제합니다.",
    ["Allow Local AI to use RAM"] = "Local AI가 RAM을 사용하도록 허용",
    ["Off: when the Local AI model you chose does not fit the free graphics memory beside the game, a smaller model that fits is loaded instead, with one notice.\n\nOn: your chosen model is kept and part of it runs from system memory (RAM) on the processor. Replies are slower, and you are told once. It needs enough free RAM, and the game may have less processor time."] = "끄기: 선택한 Local AI 모델이 게임과 나란히 여유 그래픽 메모리에 들어가지 않으면, 들어가는 더 작은 모델이 대신 로드되고 알림이 한 번 표시됩니다.\n\n켜기: 선택한 모델을 그대로 유지하며, 일부는 시스템 메모리(RAM)에서 프로세서로 실행됩니다. 응답이 느려지며, 이 사실을 한 번 알려 드립니다. 여유 RAM이 충분해야 하며, 게임이 쓸 수 있는 프로세서 시간이 줄어들 수 있습니다.",
    ["Using {model}"] = "{model} 사용 중",
    ["{model} is in use because the model you chose did not fit beside the game. Your choice is unchanged."] = "선택한 모델이 게임과 함께 들어가지 않아 {model} 모델을 사용 중입니다. 선택은 그대로 유지됩니다.",
    ["Local AI is keeping {model} as you allowed, with part of it in system memory. Replies will be slower."] = "Local AI가 허용하신 대로 {model} 모델을 유지하며, 일부는 시스템 메모리에서 실행합니다. 응답이 느려집니다.",
    ["Choosing Convai or Google Gemini turns it off. Voxtral is not used with it: a voice on Voxtral moves to Pocket and comes back when it is turned off."] = "Convai 또는 Google Gemini을 선택하면 꺼집니다. Voxtral은 이 설정과 함께 사용되지 않습니다: Voxtral 음성은 Pocket으로 바뀌고, 끄면 다시 돌아옵니다.",
    ["Convai could not sign in. Try again in a moment, or choose Google Gemini or Local AI in Settings > Conversation provider."] = "Convai에 로그인하지 못했습니다. 잠시 후 다시 시도하거나, 설정 > 대화 제공자에서 Google Gemini 또는 Local AI를 선택하세요.",
    ["Convai is answering right now, so these changes have no effect yet. Choose Google Gemini, Local AI or Custom as the conversation provider in the settings."] = "Convai가 지금 응답 중이어서 이 변경 사항은 아직 적용되지 않습니다. 설정에서 대화 제공자로 Google Gemini, Local AI 또는 사용자 지정을 선택하세요.",
    ["Convai: Google Gemini has no key yet"] = "Convai: Google Gemini 키가 아직 없음",
    ["Copy your Mistral API key first, then press Add. It fills in the endpoint URL and the model ID for Mistral (Ministral 8B) and saves your key from the clipboard. The same key powers the Voxtral cloud voice.\n\nNew Mistral accounts may not get a free API key any more."] = "먼저 Mistral API 키를 복사한 다음 Add 버튼을 누르세요. Mistral(Ministral 8B)의 엔드포인트 URL과 모델 ID가 채워지고, 클립보드의 키가 저장됩니다. 같은 키로 Voxtral 클라우드 음성도 쓸 수 있습니다.\n\n새 Mistral 계정은 더 이상 무료 API 키를 받지 못할 수 있습니다.",
    ["Copy your key from Google AI Studio first (aistudio.google.com/apikey, a Google account is enough, no card). It is read from the clipboard once and saved on this computer.\n\nThe free plan has a daily limit of about 1,000 replies, is not offered in every country, and Google may use free-plan chats to improve its products."] = "먼저 Google AI Studio에서 키를 복사하세요(aistudio.google.com/apikey, Google 계정이면 충분하며 카드는 필요 없습니다). 키는 클립보드에서 한 번 읽히고 이 컴퓨터에 저장됩니다.\n\n무료 요금제는 하루 약 1,000회 대답까지 사용할 수 있으며, 모든 국가에서 제공되지는 않습니다. 또한 Google은 무료 요금제의 대화 내용을 제품 개선에 사용할 수 있습니다.",
    ["Edit a character’s bio, speaking style, speaking rules and memories, and the prompting for each AI option, or make a character of your own, in your browser.\n\nWorks with Google Gemini, Local AI and Custom, not Convai. Changes apply from the next reply."] = "브라우저에서 캐릭터의 소개, 말투, 말하기 규칙, 기억과 AI 옵션별 프롬프트를 편집하거나 나만의 캐릭터를 만들 수 있습니다.\n\nGoogle Gemini, Local AI 및 사용자 지정에서 작동하며 Convai에서는 작동하지 않습니다. 변경 사항은 다음 응답부터 적용됩니다.",
    ["Edit characters’ bios, rules and memories, and the prompting for each AI option, in your browser.\n\nWorks with Google Gemini, Local AI and Custom, not Convai. Changes apply from the next reply."] = "브라우저에서 캐릭터의 소개, 규칙, 기억과 AI 옵션별 프롬프트를 편집할 수 있습니다.\n\nGoogle Gemini, Local AI 및 사용자 지정에서 작동하며 Convai에서는 작동하지 않습니다. 변경 사항은 다음 응답부터 적용됩니다.",
    ["From Convai or Google Gemini, turning it on selects Local AI, or Custom when Local AI is not installed. With Local AI it also selects the largest uncensored model that fits. Turning it off restores your choices."] = "Convai 또는 Google Gemini에서 켜면 Local AI가 선택되고, Local AI가 설치되어 있지 않으면 사용자 지정이 선택됩니다. Local AI를 쓸 때는 여유 그래픽 메모리에 맞는 가장 큰 무검열 모델도 함께 선택됩니다. 끄면 이전에 고른 설정이 복원됩니다.",
    ["Google Gemini (free plan)"] = "Google Gemini (무료 요금제)",
    ["Google Gemini API key"] = "Google Gemini API 키",
    ["Google Gemini has no key yet, so Convai is used. Add your key in Settings > Conversation provider."] = "Google Gemini 키가 아직 없어 Convai를 사용합니다. 설정 > 대화 제공자에서 키를 추가하세요.",
    ["Google Gemini replies are spoken by a local voice instead of the Convai cloud voice."] = "Google Gemini의 응답은 Convai 클라우드 음성 대신 로컬 음성으로 읽힙니다.",
    ["Google Gemini: key not accepted"] = "Google Gemini: 키가 허용되지 않음",
    ["The service is not available in your region."] = "사용자의 지역에서는 이 서비스를 사용할 수 없습니다.",
    ["Google accepted the key."] = "Google이 키를 승인했습니다.",
    ["Google did not accept this key. Check it in Google AI Studio, then Remove it and Add the right one."] = "Google이 이 키를 승인하지 않았습니다. Google AI Studio에서 확인한 뒤 제거를 누르고, 추가를 눌러 올바른 키를 입력하세요.",
    ["Google accepted the key, but the free allowance is used up for now."] = "Google이 키를 승인했지만, 무료 할당량이 지금은 모두 사용되었습니다.",
    ["The key is saved, but Google Gemini is not available in your region."] = "키는 저장되었지만, 사용자의 지역에서는 Google Gemini를 사용할 수 없습니다.",
    ["The key is saved, but Google could not be reached to check it."] = "키는 저장되었지만, 확인을 위해 Google에 연결할 수 없었습니다.",
    ["Google Gemini: rate limited for a minute"] = "Google Gemini: 1분 동안 제한됨",
    ["Google Gemini: free allowance used up for today"] = "Google Gemini: 오늘의 무료 할당량 모두 사용됨",
    ["Google Gemini: not available in your region"] = "Google Gemini: 지역에서 사용 불가",
    ["Google did not accept your Gemini key. Check it in Google AI Studio and add it again."] = "Google이 Gemini 키를 승인하지 않았습니다. Google AI Studio에서 확인 후 다시 추가하세요.",
    ["Your free Gemini allowance for today is used up. It resets at {time}. Use Convai or Local AI."] = "무료 Gemini 할당량을 모두 사용했습니다. {time}에 초기화. Convai 또는 Local AI를 사용하세요.",
    ["Your free Gemini allowance for today is used up. It resets tomorrow. Use Convai or Local AI."] = "무료 Gemini 할당량을 모두 사용했습니다. 내일 초기화. Convai 또는 Local AI를 사용하세요.",
    ["Google Gemini is rate limiting you. Wait a minute, then try again."] = "Google Gemini가 요청을 제한하고 있습니다. 1분 뒤 다시 시도하세요.",
    ["Google Gemini is not available in your region. Use Convai or Local AI."] = "Google Gemini는 이 지역에서 사용할 수 없습니다. Convai 또는 Local AI를 사용하세요.",
    ["Google Gemini is busy or had an error. Wait a minute, then try again."] = "Google Gemini가 바쁘거나 오류가 발생했습니다. 1분 뒤 다시 시도하세요.",
    ["Google Gemini could not be reached. Check your internet connection, then try again."] = "Google Gemini에 연결할 수 없습니다. 인터넷 연결을 확인하고 다시 시도하세요.",
    ["The Gemini model is not available right now. Try again later or use Local AI."] = "Gemini 모델을 지금 사용할 수 없습니다. 나중에 다시 시도하거나 Local AI를 사용하세요.",
    ["Google Gemini: model unavailable"] = "Google Gemini: 모델을 사용할 수 없음",
    ["Mistral (your key)"] = "Mistral (내 키)",
    ["Requires a Mistral key (add it with the Mistral preset on the Custom endpoint page)"] = "Mistral 키가 필요합니다 (Custom endpoint 페이지의 Mistral 프리셋으로 추가하세요)",
    ["The conversation limit has been reached. Try again later, or choose Local AI or Google Gemini in Settings > Conversation provider."] = "대화 한도에 도달했습니다. 나중에 다시 시도하거나, 설정 > 대화 제공자에서 Local AI 또는 Google Gemini을 선택하세요.",
    ["The longest reply, in words. Works with Google Gemini, Local AI and Custom, not Convai."] = "단어 수로 정한 가장 긴 응답입니다. Google Gemini, Local AI, Custom에서 작동하며 Convai에서는 작동하지 않습니다.",
    ["They join as a copy of the model they were made from. They talk with Google Gemini, Local AI or Custom; with Convai they talk as an ordinary person."] = "만들 때 기준이 된 모델의 복사본으로 합류합니다. Google Gemini, Local AI 또는 사용자 지정으로 대화하며, Convai에서는 일반 사람처럼 대화합니다.",
    ["Today’s Convai turns are used.\nIt resets at {time}. Try Local AI (unlimited) or Google Gemini (your own key)."] = "Convai 오늘 분량 소진.\n{time}에 초기화됩니다. Local AI(무제한) 또는 Google Gemini(본인 키)",
    ["Today’s Convai turns are used.\nTry Local AI (unlimited) or Google Gemini (your own key)."] = "Convai 오늘 분량 소진.\nLocal AI(무제한) 또는 Google Gemini(본인 키)",
    ["Today’s {limit} Convai turns are used.\nIt resets at {time}. Try Local AI (unlimited) or Google Gemini (your own key)."] = "Convai 오늘 {limit}회 소진.\n{time}에 초기화됩니다. Local AI(무제한) 또는 Google Gemini(본인 키)",
    ["Today’s {limit} Convai turns are used.\nTry Local AI (unlimited) or Google Gemini (your own key)."] = "Convai 오늘 {limit}회 소진.\nLocal AI(무제한) 또는 Google Gemini(본인 키)",
    ["Turns the content pack {name} on or off. A pack changes how the characters talk. Its prompt changes work with Google Gemini, Local AI and Custom. On Convai its world rules and its own Convai characters apply. A switch counts from the next reply, new names after a restart."] = "콘텐츠 팩 {name}을(를) 켜거나 끕니다. 팩은 캐릭터가 말하는 방식을 바꿉니다. 프롬프트 변경은 Google Gemini, Local AI, 사용자 지정에서 작동합니다. Convai에서는 팩의 월드 규칙과 팩 고유의 Convai 캐릭터가 적용됩니다. 전환은 다음 응답부터 적용되고, 새 이름은 재시작 후 적용됩니다.",
    ["What the game tells each character about this moment. A character mentions it only when it fits the talk.\n\nAn off kind is left out of every conversation provider (Convai, Google Gemini, Local AI and Custom)."] = "게임이 지금 이 순간에 대해 각 캐릭터에게 알려 주는 내용입니다. 캐릭터는 대화 흐름에 맞을 때만 언급합니다.\n\n꺼 둔 항목은 모든 대화 제공자(Convai, Google Gemini, Local AI, 사용자 지정)에서 빠집니다.",
    ["Who writes your companions’ replies. A change waits until no conversation is running.\n\nConvai free tier needs no setup and gives better replies. Convai API key uses your own key. Google Gemini uses your own free key, and its memory stays on this computer.\n\nWith Google Gemini, Local AI or Custom, Convai’s cloud voice is replaced by a local voice. Speech is recognized on this computer, so the voice key works."] = "동료의 대답을 쓰는 주체입니다. 변경은 실행 중인 대화가 없을 때까지 대기합니다.\n\nConvai 무료 플랜은 별도 설정이 필요 없고 더 나은 대답을 줍니다. Convai API 키는 본인의 키를 사용합니다. Google Gemini는 본인의 무료 키를 사용하며, 기억은 이 컴퓨터에 남습니다.\n\nGoogle Gemini, Local AI 또는 사용자 지정을 쓰면 Convai 클라우드 음성은 로컬 음성으로 대체됩니다. 음성 인식은 이 컴퓨터에서 이루어지므로 음성 키가 작동합니다.",
    ["Who writes your companions’ replies. A change waits until no conversation is running.\n\nConvai free tier needs no setup and gives better replies. Convai API key uses your own key. Google Gemini uses your own free key, and its memory stays on this computer.\n\nWith Google Gemini, Local AI or Custom, Convai’s cloud voice is replaced by a local voice. Speech recognition for the voice key is not available yet with them, so type your messages."] = "동료의 대답을 쓰는 주체입니다. 변경은 실행 중인 대화가 없을 때까지 대기합니다.\n\nConvai 무료 플랜은 별도 설정이 필요 없고 더 나은 대답을 줍니다. Convai API 키는 본인의 키를 사용합니다. Google Gemini는 본인의 무료 키를 사용하며, 기억은 이 컴퓨터에 남습니다.\n\nGoogle Gemini, Local AI 또는 사용자 지정을 쓰면 Convai 클라우드 음성은 로컬 음성으로 대체됩니다. 음성 키용 음성 인식은 아직 사용할 수 없으니 메시지를 직접 입력하세요.",
    ["You have used today’s {limit} turns, which come back at {time}. To keep talking now, choose Local AI (unlimited) or Google Gemini (with your own key)."] = "오늘의 {limit}회 대화를 모두 사용했습니다. 한도는 {time}에 초기화됩니다. 지금 계속하려면 Local AI(한도 없음) 또는 Google Gemini(본인 키 사용)을 선택하세요.",
    ["You have used today’s {limit} turns, which come back tomorrow. To keep talking now, choose Local AI (unlimited) or Google Gemini (with your own key)."] = "오늘의 {limit}회 대화를 모두 사용했습니다. 한도는 내일 초기화됩니다. 지금 계속하려면 Local AI(한도 없음) 또는 Google Gemini(본인 키 사용)을 선택하세요.",
    ["Your changes work with Google Gemini, Local AI and Custom. They do not apply to Convai."] = "변경 사항은 Google Gemini, Local AI, 사용자 지정에서 적용됩니다. Convai에는 적용되지 않습니다.",
    ["Your own characters talk only with Google Gemini, Local AI or Custom. With Convai they speak as an ordinary person."] = "내 캐릭터는 Google Gemini, Local AI, 사용자 지정과만 대화합니다. Convai에서는 일반 사람처럼 말합니다.",
    ["{name} is one of your own characters. They need Google Gemini, Local AI or Custom, so with Convai they talk as an ordinary person."] = "{name} 캐릭터는 내 캐릭터 중 하나입니다. Google Gemini, Local AI 또는 사용자 지정이 필요해서, Convai에서는 일반 사람처럼 대화합니다.",
    ["{name} is one of your own characters. They need Google Gemini, Local AI or Custom: choose one under Conversation provider in the settings."] = "{name}은(는) 당신의 캐릭터 중 하나입니다. 이 캐릭터에는 Google Gemini, Local AI 또는 Custom이 필요하므로, 설정의 대화 제공자에서 하나를 선택하세요.",
    ["This character needs Google Gemini, Local AI or Custom to answer."] = "이 캐릭터가 답하려면 Google Gemini, Local AI 또는 사용자 지정이 필요합니다.",
    ["You’ve reached today’s Convai free tier limit. It resets at {time}. To keep talking now, choose another provider in Settings > Conversation provider. Local AI is unlimited and runs on your PC. Google Gemini works with your own key."] = "오늘의 Convai (무료 플랜) 한도에 도달했습니다. {time}에 초기화됩니다. 지금 계속하려면 설정 > 대화 제공자에서 다른 제공자를 선택하세요. Local AI는 무제한이며 이 PC에서 실행됩니다. Google Gemini은 본인의 키로 사용할 수 있습니다.",
    ["You’ve reached today’s Convai free tier limit. It resets tomorrow. To keep talking now, choose another provider in Settings > Conversation provider. Local AI is unlimited and runs on your PC. Google Gemini works with your own key."] = "오늘의 Convai (무료 플랜) 한도에 도달했습니다. 한도는 내일 초기화됩니다. 지금 계속하려면 설정 > 대화 제공자에서 다른 제공자를 선택하세요. Local AI는 무제한이며 이 PC에서 실행됩니다. Google Gemini은 본인의 키로 사용할 수 있습니다.",
    ["Add a key first"] = "먼저 키를 추가하세요",
    ["Add a key to choose it"] = "키를 추가하면 선택할 수 있습니다",
    ["Asks Inworld whether your saved key is accepted. It costs nothing and no speech is made."] = "저장된 키가 허용되는지 Inworld에 확인합니다. 비용은 들지 않으며 음성은 생성되지 않습니다.",
    ["Chosen as the Companion voice"] = "동료 음성으로 선택됨",
    ["Connected"] = "연결됨",
    ["Deletes the saved key. If Inworld is your Companion voice, replies show as text until you add a key again."] = "저장된 키를 삭제합니다. Inworld가 동료 음성이면 키를 다시 추가할 때까지 답변이 텍스트로 표시됩니다.",
    ["Inworld API key"] = "Inworld API 키",
    ["Inworld cloud voice"] = "Inworld 클라우드 음성",
    ["Inworld did not accept that key."] = "Inworld가 해당 키를 허용하지 않았습니다.",
    ["Inworld is not used with Mature content."] = "Inworld는 성인 콘텐츠와 함께 사용되지 않습니다.",
    ["Inworld voice"] = "Inworld 음성",
    ["Inworld · Cloud voice"] = "Inworld · 클라우드 음성",
    ["Inworld · needs key"] = "Inworld · 키 필요",
    ["Inworld · not with Mature"] = "Inworld · 성인 콘텐츠 불가",
    ["Key refused"] = "키 거부됨",
    ["Needs your own Inworld key, from inworld.ai. Inworld’s free plan is a one-time trial of about 70 minutes of speech, then you pay as you go.\n\nCopy your key first, then press Add. It is read from the clipboard once, checked with Inworld and saved on this computer."] = "inworld.ai에서 받은 본인의 Inworld 키가 필요합니다. Inworld 무료 요금제는 약 70분 분량의 음성을 한 번만 체험할 수 있으며, 이후에는 사용한 만큼 요금을 냅니다.\n\n먼저 키를 복사한 뒤 추가를 누르세요. 키는 클립보드에서 한 번 읽혀 Inworld에서 확인되고 이 컴퓨터에 저장됩니다.",
    ["Not reachable"] = "연결할 수 없음",
    ["Not used with Mature content"] = "성인 콘텐츠에서는 사용 안 함",
    ["Ready to choose in Companion voices"] = "동료 음성에서 선택할 준비 완료",
    ["Requires an Inworld key (add it in Settings > Voices > Custom voices)"] = "Inworld 키가 필요합니다 (설정 > 음성 > 사용자 지정 음성에서 추가)",
    ["Speaks each companion in their own voice, on your own Inworld key. English only. Choose it under Companion voices, where it is listed last once a key is added."] = "각 동료를 본인의 목소리로, 본인의 Inworld 키를 사용해 말하게 합니다. 영어만 지원합니다. 동료 음성에서 선택할 수 있으며, 키를 추가하면 맨 아래에 표시됩니다.",
    ["{voice} · needs Inworld key"] = "{voice} · Inworld 키 필요",
}
